'QZ_Step_Install' => '1. QZ Tray را روی این رایانه نصب کنید — آن را رایگان از qz.io دانلود کنید، سپس اجرا کرده و در حال اجرا نگه دارید (در Windows در سینی سیستم و در macOS در نوار منو قرار می‌گیرد).',
'QZ_Step_Connect' => '2. چاپگر برچسب خود را از طریق USB متصل کنید و بررسی کنید که در سیستم‌عامل نصب شده باشد (Windows: Settings > Printers & scanners — macOS: System Settings > Printers & Scanners).',
'QZ_Step_Detect' => '3. برای شناسایی چاپگرهای این رایانه روی دکمه ⟳ کنار «نام چاپگر» در بالا کلیک کنید، سپس چاپگر برچسب خود را انتخاب کنید. برای استفاده از چاپگر پیش‌فرض رایانه، فیلد را خالی بگذارید.',
'QZ_Step_Cert' => '4. برای چاپ بدون پنجره درخواست مجوز، گواهی زیر را دانلود کرده و با نام override.crt در پوشه نصب QZ Tray کپی کنید (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). سپس QZ Tray را ببندید و دوباره اجرا کنید.',
'QZ_Step_Test' => '5. روی «چاپ برچسب آزمایشی» در زیر کلیک کنید. اگر QZ Tray درخواست مجوز کرد، روی Allow کلیک کنید — با نصب گواهی، دیگر درخواست نخواهد کرد.',
'QZ_Step_Save' => '6. برای ذخیره این تنظیمات روی ثبت کلیک کنید. اکنون برچسب‌های صفحه چاپ بارکد مستقیماً و بدون پنجره چاپ مرورگر روی این چاپگر چاپ می‌شوند.',
'QZ_Setup_Note' => 'QZ Tray روی رایانه‌ای که از آن مرور می‌کنید اجرا می‌شود، بنابراین حتی زمانی که Stocky روی سرور راه دور میزبانی شود نیز کار می‌کند. هر رایانه‌ای که برچسب چاپ می‌کند باید QZ Tray را نصب داشته باشد.',

// PWA settings tab — installable app identity
'PWA_Enabled' => 'فعال‌سازی برنامه قابل نصب',
'PWA_Enabled_Help' => 'به مرورگرها اجازه می‌دهد نصب این برنامه را روی تلفن‌ها، تبلت‌ها و رایانه‌ها پیشنهاد دهند و صفحات را برای کار آفلاین در حافظه نهان نگه می‌دارد. خاموش کردن این گزینه، پیشنهاد نصب را در همه جا حذف کرده و حافظه نهان را در بازدید بعدی پاک می‌کند.',
