'PWA_App_Name' => 'نام برنامه',
'PWA_App_Name_Help' => 'در پیشنهاد نصب و فهرست برنامه‌ها نمایش داده می‌شود. برای استفاده از نام برنامه در تنظیمات ظاهری خالی بگذارید.',
'PWA_Short_Name' => 'نام کوتاه',
'PWA_Short_Name_Help' => 'زیر آیکون در صفحه اصلی نمایش داده می‌شود، جایی که نام‌های بلند کوتاه می‌شوند. برای استفاده از بخش پیش از "|" در نام برنامه خالی بگذارید.',
'PWA_Description' => 'توضیحات',
