'PWA_Display_Mode' => 'حالت نمایش',
'PWA_Display_Mode_Help' => 'standalone نوار مرورگر را پنهان می‌کند؛ fullscreen نوار وضعیت را نیز پنهان می‌کند؛ browser یک زبانه معمولی باز می‌کند.',
