'PWA_Preview' => 'پیش‌نمایش',
'PWA_View_Manifest' => 'مشاهده فایل manifest',
'PWA_Reinstall_Notice' => 'دستگاه‌هایی که برنامه را قبلاً نصب کرده‌اند، تا زمان حذف و نصب مجدد، نام و آیکون قدیمی را حفظ می‌کنند.',

'Label_Render_Mode' => 'نحوه رندر برچسب',
'Label_Render_Mode_Hint' => 'نحوه ترسیم برچسب. فونت‌های چاپگر سریع‌ترین روش است و واضح‌ترین بارکد را می‌دهد، اما فقط نویسه‌های پایه لاتین را با فونت خود چاپگر چاپ می‌کند. تصویر پیش‌نمایش طراحی برچسب شما را دقیقاً بازتولید می‌کند — با فونت انتخابی شما، به هر زبانی — همان‌طور که نرم‌افزارهای تخصصی برچسب انجام می‌دهند.',
'Render_Native' => 'فونت‌های چاپگر (سریع‌ترین)',
'Render_Raster' => 'تصویر پیش‌نمایش (طراحی دقیق)',
'Label_Width_Mm' => 'عرض برچسب (mm)',
'Label_Height_Mm' => 'ارتفاع برچسب (mm)',
'Label_Size_Hint' => 'اندازه فیزیکی یک برچسب روی رول. باید دقیقاً با برچسب‌های بارگذاری‌شده مطابقت داشته باشد — اندازه نادرست باعث می‌شود چاپگر فاصله را در جای اشتباه جستجو کند و هر برچسب بیشتر از جای خود جابه‌جا چاپ شود.',
'Calibrate_Labels' => 'کالیبره کردن برچسب‌ها',
'Calibrate_Labels_Hint' => 'چاپگر چند برچسب را عبور می‌دهد تا برچسب و فاصله را اندازه‌گیری کند. پس از بارگذاری رول جدید یا زمانی که موقعیت چاپ جابه‌جا می‌شود، یک بار اجرا کنید.',
'Calibration_Sent' => 'کالیبراسیون آغاز شد — چاپگر چند برچسب خالی را برای اندازه‌گیری عبور می‌دهد. پس از توقف، یک چاپ آزمایشی انجام دهید.',
'Label_Printer_Dpi' => 'وضوح هد چاپ',
'Label_Printer_Dpi_Hint' => 'بیشتر چاپگرهای برچسب 203 dpi هستند. مطمئن نیستید؟ از دکمه «یافتن وضوح» در زیر استفاده کنید — پاسخ را چاپ می‌کند.',
'Find_Resolution' => 'یافتن وضوح',
'Find_Resolution_Hint' => 'دو برچسب با علامت 203 و 300 چاپ می‌کند. برچسب صحیح یک مستطیل کامل با حاشیه کوچک و یکنواخت در هر چهار طرف نشان می‌دهد؛ برچسب نادرست لبه‌هایش ناقص است یا به برچسب بعدی می‌رسد.',
'Dpi_Test_Sent' => 'دو برچسب با علامت 203 و 300 در حال چاپ است. برچسب صحیح یک مستطیل کامل با حاشیه کوچک و یکنواخت در هر چهار طرف نشان می‌دهد — «وضوح هد چاپ» را روی همان عدد تنظیم و ذخیره کنید.',
'Label_Offset_X' => 'جابه‌جایی افقی (mm)',
'Label_Offset_X_Hint' => 'چاپ را روی برچسب به طرفین جابه‌جا می‌کند. زمانی استفاده کنید که متن در یک لبه بریده می‌شود — مثلاً 2.5 زمانی که برچسب سفید در وسط کاغذ پشتی عریض‌تری قرار دارد. با گام‌های 0.5 تنظیم کنید.',
'Label_Offset_Y' => 'جابه‌جایی عمودی (mm)',
'Label_Offset_Y_Hint' => 'چاپ را در طول برچسب جابه‌جا می‌کند. اگر بالای طرح بریده یا ناپدید شده است افزایش دهید؛ اگر خیلی پایین‌تر شروع می‌شود کاهش دهید.',
'Feed_To_Tear' => 'عبور تا لبه برش',
'Feed_To_Tear_Hint' => 'پس از هر کار، برچسب را تا تیغه برش جلو می‌برد. اگر برچسب‌ها به سمت پایین جابه‌جا یا بین دو برچسب تقسیم چاپ می‌شوند، خاموش بگذارید — بسیاری از چاپگرها پیش از برچسب بعدی به عقب برنمی‌گردند.',
