'Orders_Guide' => 'راهنمای سفارش‌ها',
'Ord_Guide_Intro' => 'نحوه انتقال سفارش ثبت‌شده در فروشگاه آنلاین به موجودی و حساب‌های شما، و محل واقعی ثبت پول.',
'Ord_Guide_Lifecycle_Title' => 'وضعیت سفارش',
'Ord_Guide_Lifecycle_Pending' => 'یک سفارش جدید در انتظار بررسی شما. فقط سفارش در انتظار را می‌توان تأیید یا لغو کرد.',
'Ord_Guide_Lifecycle_Confirmed' => 'شما سفارش را پذیرفتید. Stocky یک فروش در انبار انتخابی شما ایجاد کرده و موجودی را کسر می‌کند — این فروش، رکوردی است که گزارش‌های موجودی، پرداخت و سود از آن خوانده می‌شوند.',
'Ord_Guide_Lifecycle_Shipped' => 'شما سفارش را ارسال کردید. فقط مرحله تحویل: موجودی هنگام تأیید کسر شده بود.',
'Ord_Guide_Lifecycle_Delivered' => 'مشتری سفارش را دریافت کرد. این همان چیزی است که مهلت مرجوعی را آغاز می‌کند.',
'Ord_Guide_Lifecycle_Cancelled' => 'سفارش پیش از تأیید کنار گذاشته شد، بنابراین هیچ فروشی ایجاد نشد و موجودی کسر نشد.',
'Ord_Guide_PaymentStatus_Tip' => 'هنگام تسویه تعیین می‌شود و اینجا قابل ویرایش نیست. برای مشاهده نحوه ثبت پرداخت کلیک کنید.',
'Ord_Guide_Payment_Title' => 'وضعیت پرداخت',
'Ord_Guide_Payment_Intro' => 'این ستون نحوه پرداختی را که مشتری هنگام تسویه انتخاب کرده ثبت می‌کند. توسط فروشگاه تعیین می‌شود و از این صفحه قابل ویرایش نیست — خود پول در فروشی که با تأیید سفارش ایجاد می‌شود پیگیری می‌شود.',
'Ord_Guide_Payment_Paid' => 'مشتری قبلاً از طریق درگاه پرداخت به‌صورت آنلاین پرداخت کرده است. تأیید سفارش، فروش را به‌صورت پرداخت‌شده ایجاد کرده و پرداخت را برای شما ثبت می‌کند — کار دیگری لازم نیست.',
'Ord_Guide_Payment_Pending' => 'پرداخت در محل، انتقال بانکی یا روش پرداخت بعدی دیگر. تأیید سفارش، فروش را به‌صورت پرداخت‌نشده ایجاد می‌کند، بنابراین پس از دریافت پول، خودتان آن را ثبت می‌کنید — مراحل زیر را ببینید.',
'Ord_Guide_Payment_Failed' => 'درگاه پرداخت را رد کرد یا مشتری آن را رها کرد. سفارش به‌صورت خودکار لغو می‌شود.',
'Ord_Guide_MarkPaid_Title' => 'تغییر پرداخت از در انتظار به پرداخت‌شده',
'Ord_Guide_MarkPaid_Step1' => 'ابتدا سفارش را اینجا تأیید کنید — تأیید است که فروش را ایجاد می‌کند.',
'Ord_Guide_MarkPaid_Step2' => 'فروش‌ها > همه فروش‌ها را باز کنید و آن فروش را پیدا کنید (همان مشتری؛ صفحه جزئیات سفارش آنلاین مبدأ را نشان می‌دهد).',
'Ord_Guide_MarkPaid_Step3' => 'منوی عملیات ردیف را باز کرده و ایجاد پرداخت را انتخاب کنید.',
'Ord_Guide_MarkPaid_Step4' => 'مبلغ، روش پرداخت و تاریخ را وارد کرده و ذخیره کنید. فروش بسته به مبلغ، خودبه‌خود به جزئی یا پرداخت‌شده تغییر می‌کند.',
'Ord_Guide_MarkPaid_Note' => 'وضعیت پرداخت نمایش‌داده‌شده اینجا همچنان انتخاب هنگام تسویه را نشان می‌دهد و تغییر نمی‌کند. فروش، رکورد حسابداری است و همان است که گزارش‌های پرداخت و سود شما را تغذیه می‌کند. برای بررسی یا ویرایش آنچه وارد کرده‌اید، از نمایش پرداخت‌ها در فروش استفاده کنید.',
'Ord_Guide_Notes_Title' => 'خوب است بدانید',
'Ord_Guide_Note_Warehouse' => 'انباری که هنگام تأیید انتخاب می‌کنید، محل کسر موجودی را تعیین می‌کند. انبارهایی که نمی‌توانند کل سفارش را پوشش دهند، در آن فهرست با علامت ناموجود مشخص می‌شوند.',
'Ord_Guide_Note_Preorder' => 'اقلام پیش‌سفارش از بررسی موجودی معاف هستند، بنابراین سفارش شامل آن‌ها حتی در صورت عدم موجودی نیز قابل تأیید است.',
'Ord_Guide_Note_Flagged' => 'برچسب علامت‌گذاری‌شده یعنی سفارش هنگام تسویه در بررسی تقلب مشکوک تشخیص داده شده است. نشانگر را روی برچسب ببرید تا دلیل را ببینید و پیش از تأیید، سفارش را بررسی کنید.',
'Ord_Guide_Note_Cancel' => 'لغو فقط تا زمانی که سفارش در انتظار است امکان‌پذیر است. پس از تأیید، آن را از طریق فروش یا مرجوعی مشتری برگردانید.',


