// Variants guide drawer (product form).
'Guide' => 'راهنما',
'Variants_Guide' => 'راهنمای تنوع‌ها',
'VG_Intro' => 'کالای متغیر به‌صورت چند تنوع فروخته می‌شود. آن‌ها را از گزینه‌ها (توصیه‌شده) یا به‌صورت فهرست ساده‌ای از نام‌ها بسازید. هر تنوع کد، قیمت، تصویر و موجودی مخصوص خود را دارد.',
'VG_Options_Title' => 'حالت گزینه‌ها (رنگ، سایز...)',
'VG_Opt_Step1' => 'کلید سربرگ کارت را روی «گزینه‌ها» نگه دارید.',
'VG_Opt_Step2' => 'نام گزینه‌ای مانند رنگ یا سایز را تایپ کنید یا یکی از پیشنهادها را انتخاب کنید.',
'VG_Opt_Step3' => 'یک مقدار (مثلاً قرمز) تایپ کرده و Enter را بزنید. برای هر مقدار تکرار کنید؛ ویرگول نیز مقادیر را جدا می‌کند. برای حذف یک مقدار روی x آن کلیک کنید.',
'VG_Opt_Step4' => 'برای گزینه دوم یا سوم روی «افزودن گزینه» کلیک کنید (حداکثر 3 گزینه).',
'VG_Opt_Step5' => 'روی «ایجاد تنوع‌ها» کلیک کنید. برای هر ترکیب یک ردیف ایجاد شده و نام آن به‌صورت خودکار ساخته می‌شود، مثلاً "Red / S".',
'VG_Opt_Step6' => 'بهای تمام‌شده و قیمت را در هر ردیف وارد کنید، یا یک مقدار در «اعمال برای همه» تایپ کرده و برای کپی آن در همه ردیف‌ها روی بهای تمام‌شده یا قیمت کلیک کنید.',
'VG_Opt_Step7' => 'کدها برای شما ایجاد می‌شوند. کد دلخواه خود را تایپ کنید یا برای ایجاد کد دیگر روی آیکون بازخوانی کلیک کنید.',
'VG_Opt_Step8' => 'اختیاری: «نمونه‌های رنگ» را در یک گزینه علامت بزنید و برای هر مقدار یک رنگ انتخاب کنید؛ فروشگاه آن را به‌صورت یک نقطه رنگی نمایش می‌دهد.',
'VG_Rows_Title' => 'ردیف‌های تنوع',
'VG_Rows_Text' => 'هر ردیف دارای تصویر، کد، بارکد، بهای تمام‌شده، قیمت، قیمت عمده و حداقل قیمت فروش است. هنگام ایجاد کالا می‌توانید موجودی اول دوره هر انبار را نیز برای هر تنوع وارد کنید. برچسب «ناقص» یعنی ردیف برای یکی از گزینه‌ها مقدار ندارد.',
'VG_List_Title' => 'حالت فهرست ساده',
'VG_List_Text' => 'نام یک تنوع را تایپ کرده و Enter را بزنید (یا روی افزودن کلیک کنید) تا یک ردیف اضافه شود، سپس کد و قیمت‌های آن را وارد کنید. این رفتار کلاسیک است و برای کالاهای موجود در دسترس باقی می‌ماند.',
'VG_Edit_Title' => 'ویرایش بعدی',
'VG_Edit_1' => 'یک مقدار اضافه کرده و روی «ایجاد تنوع‌ها» کلیک کنید: فقط ترکیب‌های ناموجود اضافه می‌شوند. ردیف‌های موجود کدها، قیمت‌ها و سابقه خود را حفظ می‌کنند.',
'VG_Edit_2' => 'حذف یک مقدار یا گزینه، ردیف‌هایی را که از آن استفاده می‌کنند حذف می‌کند. ردیف‌هایی که قبلاً ذخیره شده‌اند، پس از تأیید، هنگام ذخیره کالا پاک می‌شوند.',
'VG_Edit_3' => 'تنوعی که هنوز موجودی دارد قابل حذف نیست. ابتدا موجودی آن را تعدیل یا منتقل کنید.',
'VG_Edit_4' => 'تغییر به «فهرست ساده» ردیف‌ها و نام‌های آن‌ها را حفظ می‌کند اما تعاریف گزینه‌ها را حذف می‌کند.',
'VG_Store_Title' => 'در فروشگاه آنلاین',
'VG_Store_Text' => 'مشتریان برای هر گزینه یک مقدار انتخاب می‌کنند، مثلاً ابتدا رنگ و سپس سایز. ترکیب‌های ناموجود غیرفعال هستند و موارد ناموجود در انبار خط می‌خورند. تنوع انتخاب‌شده همان است که به سبد خرید اضافه می‌شود.',
'Choose_Source' => 'انتخاب منبع',
