'Warehouse_Logo_Help' => 'لوگویی که روی فاکتورها و رسیدهای POS این انبار چاپ می‌شود. برای استفاده از لوگوی شرکت خالی بگذارید.',
'Warehouse_Invoice_Footer_Help' => 'یادداشت اضافی که پایین فاکتورهای صادرشده توسط این انبار چاپ می‌شود.',
'Issued_By' => 'صادرشده توسط',
