'Enable_Warehouse_Letterhead_Hint' => 'انبار صادرکننده را روی فاکتورها، رسیدهای POS و صفحه عمومی فاکتور چاپ کنید: نام آن جایگزین نام شرکت می‌شود و آدرس، تلفن، ایمیل، لوگو و یادداشت پاورقی آن جایگزین موارد شرکت می‌شوند. هر فیلدی که در انبار خالی بماند، از تنظیمات کلی شرکت استفاده می‌کند.',
