'Upd_Guide_Before_Admin' => 'مطمئن شوید با حساب مدیری وارد شده‌اید که مجوز {perm} را دارد. هیچ کس دیگری نمی‌تواند به‌روزرسان را ببیند یا اجرا کند.',
'Upd_Guide_Before_Quiet' => 'زمان خلوتی را انتخاب کنید: در طول به‌روزرسانی، برنامه برای مدت کوتاهی به حالت نگهداری می‌رود و سایر کاربران نمی‌توانند وارد شوند.',
'Upd_Guide_Before_No_Manual' => 'شما {not} نیازی به پشتیبان‌گیری دستی، استخراج فایل‌ها، اجرای فرمان، ویرایش فایل‌های پیکربندی یا دست زدن به پایگاه داده ندارید — به‌روزرسان همه این کارها را به‌طور خودکار انجام می‌دهد. (البته یک پشتیبان دستی اضافی هرگز ضرری ندارد.)',
'Upd_Not' => 'هرگز',
'Upd_Guide_Code_Overwritten' => 'اگر کد برنامه را به‌صورت دستی تغییر داده‌اید، تغییرات شما با به‌روزرسانی بازنویسی می‌شوند. داده‌ها، بارگذاری‌ها، تنظیمات و .env شما همیشه حفظ می‌شوند.',
'Upd_Guide_Running_Title' => '2. اجرای به‌روزرسانی',
'Upd_Guide_Run_Open' => '{path} (همین صفحه) را باز کرده و در زبانه {tab} بمانید.',
'Upd_Guide_Run_Upload' => '{upload}: روی کادر بارگذاری کلیک کنید یا بسته دانلودشده را به آن بکشید. فایل‌های بزرگ در قطعات کوچک بارگذاری می‌شوند، بنابراین روی هاست‌های اشتراکی با محدودیت بارگذاری پایین نیز کار می‌کند. یک checksum از بارگذاری‌های خراب یا ناقص جلوگیری می‌کند.',
'Upd_Upload_The_Zip' => 'بارگذاری ZIP',
'Upd_Guide_Run_Validation' => '{auto} پس از بارگذاری (می‌توانید با دکمه {button} آن را دوباره اجرا کنید). سیستم موارد زیر را بررسی می‌کند: سلامت ZIP، ساختار و کامل بودن بسته، سازگاری نسخه (بازگشت به نسخه قدیمی‌تر رد می‌شود)، نسخه و افزونه‌های لازم PHP، مجوزهای فایل، فضای خالی دیسک، اتصال پایگاه داده، پیکربندی و اینکه به‌روزرسانی دیگری در حال اجرا نباشد.',
'Upd_Validation_Runs_Automatically' => 'اعتبارسنجی به‌طور خودکار اجرا می‌شود',
'Upd_Guide_Run_Review' => 'پنل {panel} را بررسی کنید. دکمه {button} فقط زمانی ظاهر می‌شود که همه بررسی‌های حیاتی موفق باشند. اگر بررسی‌ای ناموفق باشد، پیام دقیقاً می‌گوید چه چیزی را اصلاح کنید.',
'Upd_Guide_Run_Click' => 'روی {button} کلیک کرده و تأیید کنید. سپس کافی است {keep} و نوار پیشرفت را دنبال کنید. سیستم به ترتیب موارد زیر را انجام می‌دهد:',
'Upd_Keep_Page_Open' => 'این صفحه را باز نگه دارید',
'Upd_Guide_Phase_Backup' => '{label} — یک dump کامل پایگاه داده، یک ZIP از همه فایل‌های برنامه که به‌روزرسانی ممکن است تغییر دهد و یک کپی از {env} ایجاد و {verified} می‌شوند. بارگذاری‌های شما ({images}) و {storage} هرگز توسط به‌روزرسانی تغییر نمی‌کنند، بنابراین بایگانی نمی‌شوند. اگر پشتیبان ایجاد نشود، به‌روزرسانی همین‌جا متوقف شده و هیچ چیز تغییر نمی‌کند.',
'Upd_Verified' => 'تأیید',
'Upd_Guide_Phase_Prepare' => '{label} — نسخه جدید در یک ناحیه موقت استخراج شده و دوباره اعتبارسنجی می‌شود. برنامه زنده هنوز دست‌نخورده است.',
'Upd_Guide_Phase_Maintenance' => '{label} — حالت نگهداری فعال می‌شود؛ بازدیدکنندگان صفحه دوستانه «به‌زودی برمی‌گردیم» را می‌بینند.',
'Upd_Guide_Phase_Files' => '{label} — فایل‌های جدید تقریباً بلافاصله جایگزین می‌شوند؛ فایل‌های قدیمی برای بازگردانی کنار گذاشته می‌شوند. مسیرهای محافظت‌شده ({env}، {storage}، {images}) هرگز جایگزین نمی‌شوند.',
'Upd_Guide_Phase_Database' => '{label} — migrationها اجرا شده، سپس مجوزها، ترجمه‌ها و قالب‌ها تازه‌سازی می‌شوند.',
'Upd_Guide_Phase_Cache' => '{label} — همه کش‌ها پاک و بازسازی می‌شوند.',
'Upd_Guide_Phase_Verify' => '{label} — بررسی‌های سلامت تأیید می‌کنند که نسخه جدید راه‌اندازی می‌شود، پایگاه داده کار می‌کند، همه migrationها اجرا شده‌اند و پیکربندی معتبر است.',
'Upd_Guide_Phase_Done' => '{label} — حالت نگهداری برداشته شده و فایل‌های موقت پاک‌سازی می‌شوند.',
'Upd_Guide_Run_Success' => 'وقتی {success} را دیدید، روی {reload} کلیک کرده و مرورگر خود را به‌طور کامل تازه‌سازی کنید ({keys}) تا فایل‌های جدید پنل مدیریت بارگذاری شوند.',
'Upd_Update_Successful_Short' => 'به‌روزرسانی موفق بود',
'Upd_Guide_No_Internet' => 'در طول به‌روزرسانی به اینترنت نیازی نیست — همه چیز از ZIP بارگذاری‌شده می‌آید. قطع اتصال یا بستن مرورگر به‌روزرسانی را خراب نمی‌کند: سرور دقیقاً به خاطر دارد کجا متوقف شده است.',
'Upd_Guide_Wrong_Title' => '3. اگر مشکلی پیش آمد',
'Upd_Guide_Wrong_Rollback' => '{label} — اگر پس از شروع تغییر فایل‌ها مشکلی رخ دهد (خطای استخراج، شکست migration، شکست بررسی سلامت، پر شدن دیسک، …)، سیستم به‌طور خودکار فایل‌های قبلی و پایگاه داده را از پشتیبان تأییدشده بازیابی کرده، حالت نگهداری را برمی‌دارد و {message} را گزارش می‌کند. دقیقاً به نقطه شروع بازمی‌گردید.',
'Upd_Automatic_Rollback' => 'بازگردانی خودکار',
'Upd_Failed_Previous_Restored' => 'به‌روزرسانی ناموفق بود — نسخه قبلی بازیابی شد',
'Upd_Guide_Wrong_Interrupted' => '{label} (راه‌اندازی مجدد سرور، timeout، بسته شدن مرورگر، قطع برق) — وقتی این صفحه را دوباره باز کنید، یک نوار قرمز دو گزینه ایمن ارائه می‌دهد: {resume} (از همان مرحله‌ای که متوقف شده ادامه می‌دهد) یا {rollback} (نسخه قبلی را از پشتیبان بازیابی می‌کند).',
'Upd_Interrupted_Update' => 'به‌روزرسانی قطع‌شده',
'Upd_Guide_Wrong_Unreachable' => '{label} — از {console} مستقل در {path} استفاده کنید. حتی زمانی که سایت در حالت نگهداری است یا فایل‌های پنل مدیریت خراب شده‌اند کار می‌کند و همان اقدامات ادامه / بازگردانی را ارائه می‌دهد. همچنین یک لینک کم‌رنگ «دسترسی مدیر» در پایین صفحه نگهداری وجود دارد.',
'Upd_Admin_Unreachable' => 'پنل مدیریت در دسترس نیست',
'Upd_Recovery_Console' => 'کنسول بازیابی',
'Upd_Guide_Wrong_Locked_Out' => '{label} — در حین اجرای به‌روزرسانی، این صفحه یک {link} نمایش می‌دهد. اگر نیاز به بازگشت دارید (مثلاً پس از منقضی شدن نشست) آن را ذخیره کنید؛ این لینک شما را از صفحه نگهداری عبور می‌دهد تا دوباره وارد شوید.',
'Upd_Locked_Out_Maintenance' => 'قفل شدن به‌دلیل حالت نگهداری',
'Upd_Bypass_Link' => 'لینک عبور',
'Upd_Guide_Wrong_Concurrent' => '{label} — آن‌ها {message} را می‌بینند. فقط یک به‌روزرسانی در هر زمان می‌تواند اجرا شود.',
'Upd_Another_Admin_Updating' => 'مدیر دیگری هم‌زمان قصد به‌روزرسانی دارد',
'Upd_Guide_Backups_Title' => '4. پشتیبان‌ها و بازیابی',
'Upd_Guide_Backups_Created' => 'هر به‌روزرسانی {before} دست زدن به هر چیزی یک پشتیبان ایجاد می‌کند: همه فایل‌های برنامه که به‌روزرسانی ممکن است جایگزین کند، یک کپی از {env} و یک dump کامل پایگاه داده. بارگذاری‌ها و {storage} هرگز توسط به‌روزرسانی تغییر نمی‌کنند و بنابراین بخشی از آن نیستند — خودتان از آن‌ها پشتیبان نگه دارید. پشتیبان‌ها در {path} قرار دارند و هرگز از وب قابل دسترسی نیستند.',
'Upd_Before' => 'پیش از',
'Upd_Guide_Backups_Panel' => 'پنل {panel} در زبانه {tab} آن‌ها را با تاریخ، نسخه و اندازه فهرست می‌کند. از آنجا می‌توانید هر پشتیبان کامل را {restore} کنید (فایل‌ها + پایگاه داده — ابتدا یک کپی ایمنی از پایگاه داده فعلی گرفته می‌شود) یا پشتیبان‌های قدیمی را {delete} کنید.',
'Upd_Restore_Verb' => 'بازیابی',
'Upd_Delete_Verb' => 'حذف',
'Upd_Guide_Backups_Retention' => 'از {keep} برای تعیین تعداد پشتیبان‌های نگه‌داشته‌شده استفاده کنید؛ پشتیبان‌های قدیمی‌تر پس از هر به‌روزرسانی موفق به‌طور خودکار حذف می‌شوند. تنها پشتیبان کامل باقیمانده هرگز قابل حذف نیست — همیشه راه بازگشتی دارید.',
'Upd_Guide_Manual_Title' => '5. به‌روزرسانی دستی (روش جایگزین)',
'Upd_Guide_Manual_Text' => 'اگر ترجیح می‌دهید به‌صورت دستی به‌روزرسانی کنید یا بارگذار روی سرور شما قابل استفاده نیست، دستورالعمل گام‌به‌گام در زبانه {tab} همین صفحه را دنبال کنید.',
'Upd_Guide_Clear_Cache_First' => 'اگر پس از هر به‌روزرسانی صفحات خراب یا خالی به نظر می‌رسند، ابتدا کش مرورگر خود را پاک کنید — تقریباً همیشه علت همین است.',
'Upd_Restore_Backup_Confirm' => 'این پشتیبان بازیابی شود؟ فایل‌ها و پایگاه داده فعلی با پشتیبان جایگزین می‌شوند. ابتدا یک کپی ایمنی از پایگاه داده فعلی گرفته می‌شود. (v{version} — {date})',
'Woo_Guide_Lead' => 'نحوه هماهنگ ماندن فروشگاه WooCommerce با ERP. خطوط cron زیر برای همین سرور ساخته شده‌اند، بنابراین می‌توان آن‌ها را مستقیماً روی آن کپی کرد.',
'Woo_Guide_Ways_Note' => 'برخلاف Shopify، WooCommerce به‌خودی‌خود چیزی به ERP ارسال نمی‌کند — اینجا گیرنده webhook وجود ندارد، بنابراین همه داده‌های {in} طبق زمان‌بندی می‌رسند. فقط موجودی {out} می‌تواند فوری باشد.',
'Woo_In' => 'ورودی',
'Woo_Out' => 'خروجی',
'Woo_Guide_Both_Ways_Title' => 'هر دو روش ابتدا به این نیاز دارند',
'Woo_Api_Keys' => 'کلیدهای API',
'Woo_Guide_Api_Keys_Text' => '{path}، مجوز {perm}. کلید مصرف‌کننده و رمز را همراه با URL فروشگاه — آدرس سایت شما بدون اسلش انتهایی، مثلاً {example} — در زبانه {settings} کپی کنید.',
'Woo_Credentials_Saved' => 'اعتبارنامه‌ها ذخیره شد',
'Woo_Not_Configured_Yet' => 'هنوز پیکربندی نشده',
'Woo_Guide_Wp_App_Password_Title' => 'رمز برنامه WordPress (اختیاری)',
'Woo_Guide_Wp_App_Password_Text' => 'فقط برای تصاویر محصول استفاده می‌شود. API WooCommerce محصولات، موجودی، دسته‌بندی‌ها، برندها، مشتریان و سفارش‌ها را منتقل می‌کند؛ API WordPress کتابخانه رسانه را جستجو کرده و تصویری را که هنوز آنجا نیست بارگذاری می‌کند.',
'Woo_Guide_Wp_App_Password_Note' => 'از یک کاربر WordPress که می‌تواند رسانه را مدیریت کند استفاده کرده و رمز را در {path} ایجاد کنید. اگر هر دو فیلد را خالی بگذارید، همه چیز همچنان همگام‌سازی می‌شود — فقط پیوست تصویر رد می‌شود.',
'Woo_Guide_Pick_Way_Title' => 'سپس نحوه هماهنگ ماندن را انتخاب کنید',
'Woo_Right_Away' => 'فوری',
'Woo_Stock_Live' => 'موجودی زنده',
'Woo_Stock_Not_Live' => 'موجودی زنده نیست',
'Woo_Guide_Realtime_Lead' => 'فقط یک جهت: موجودی و محصولاتی که از ERP خارج می‌شوند. سفارش‌ها و ویرایش‌های محصول در WooCommerce همچنان طبق زمان‌بندی می‌رسند — زبانه دیگر را ببینید.',
'Woo_Push_Stock_On_Change' => 'ارسال موجودی به محض تغییر',
'Woo_Setting_People_Miss' => 'این همان تنظیمی است که اغلب نادیده گرفته می‌شود',
'Woo_Guide_Pos_Sale_Not_Reach' => 'فروش POS به‌خودی‌خود به WooCommerce {not}. اگر خاموش باشد، فروشگاه فقط در همگام‌سازی بعدی موجودی — به‌طور پیش‌فرض یک ساعت — مطلع می‌شود و در این فاصله ممکن است واحدی را بفروشد که قبلاً در صندوق فروخته‌اید.',
'Woo_Does_Not' => 'نمی‌رسد',
'Woo_Guide_Tick_Instant' => 'گزینه {option} را در زبانه {settings} تیک بزنید. کل راه‌اندازی همین است — بدون worker، بدون cron. هر فروش، مرجوعی، تعدیل، انتقال و خرید دریافت‌شده، بلافاصله پس از ذخیره، فقط موجودی همان محصولات را ارسال می‌کند و یک فروش بیست‌ردیفی یک ارسال است، نه بیست. صندوق هرگز منتظر آن نمی‌ماند.',
'Woo_Currently' => 'در حال حاضر:',
'Woo_Instant_On_Text' => 'روشن — موجودی هنگام تغییر ارسال می‌شود',
'Woo_Instant_Off_Text' => 'خاموش — موجودی فقط طبق زمان‌بندی',
'Woo_Guide_Instant_Note' => 'فقط محصولاتی که از قبل به WooCommerce پیوند داده شده‌اند ارسال می‌شوند — محصولی که هرگز همگام‌سازی نشده چیزی در فروشگاه برای اصلاح ندارد. محصولات متغیر از طریق والد خود ارسال می‌شوند و یک کمبو هنگام جابه‌جایی هر یک از اجزایش دوباره ارسال می‌شود. عملیات گروهی (حذف محصول، بازنشانی انبار) موجودی را بدون ایجاد رویداد می‌نویسند، که یکی از دلایل نگه‌داشتن همگام‌سازی ساعتی موجودی است.',
'Woo_Push_Products_On_Save' => 'ارسال محصولات به محض ذخیره',
'Woo_Guide_Tick_Auto_Products' => 'گزینه {option} را در زبانه {settings} تیک بزنید تا محصولی که در Stocky ایجاد، ویرایش یا تکثیر می‌شود بلافاصله پس از ذخیره به WooCommerce ارسال شود — جزئیات، قیمت، تنوع‌ها و تصاویر، سپس موجودی آن. محصول جدید به‌جای انتظار برای همگام‌سازی شبانه محصولات، بلافاصله در فروشگاه ایجاد می‌شود.',
'Woo_On' => 'روشن',
'Woo_Off' => 'خاموش',
'Woo_Guide_Bulk_Imports_Note' => 'ورودهای گروهی یکی‌یکی ارسال نمی‌شوند — پس از ورود، همگام‌سازی محصولات را اجرا کنید. ابتدا دسته‌بندی‌ها و برندها را همگام‌سازی کنید تا محصول ارسالی در دسته‌بندی درست قرار گیرد.',
'Woo_Nothing_Else_To_Install' => 'نیازی به نصب چیز دیگری نیست',
'Woo_Guide_Same_Process' => 'بدون queue worker، بدون ورودی cron. ارسال در همان فرایندی اجرا می‌شود که فروش را پردازش کرده، {after} بازگشت پاسخ، بنابراین صندوق هرگز منتظر WooCommerce نمی‌ماند. ارسال‌ها هرگز هم‌پوشانی ندارند: تغییرات ایجادشده در حین اجرای یک ارسال، منتظر آن می‌مانند و بلافاصله پس از آن ارسال می‌شوند.',
'Woo_After' => 'پس از',
'Woo_Guide_Shop_Stops_Answering' => 'فروشگاهی که پاسخ نمی‌دهد پس از هشت ثانیه رها می‌شود و ارسال‌ها به مدت پنج دقیقه متوقف می‌شوند تا هر فروش دوباره منتظر آن نماند؛ تغییرات این فاصله با اولین ارسال پس از توقف ارسال می‌شوند و همگام‌سازی ساعتی موجودی در هر صورت عقب‌ماندگی را جبران می‌کند. هر توقف در زبانه گزارش‌ها ثبت می‌شود.',
'Woo_Guide_Artisan_Exception' => 'یک استثنا: تغییر موجودی ایجادشده توسط یک فرمان artisan پاسخی ندارد که پس از آن اجرا شود، بنابراین به‌جای آن در صف {queue} قرار می‌گیرد. برای ارسال سریع این موارد نیز، آن صف را پردازش کنید:',
'Woo_Cron_Line_Copied' => 'خط cron کپی شد',
'Woo_Command_Copied' => 'فرمان کپی شد',
