'Woo_On_A_Schedule' => 'طبق زمان‌بندی',
'Woo_Guide_Scheduled_Lead' => 'همه چیز هر چند وقت یک بار در هر دو جهت دوباره بررسی می‌شود. سفارش‌ها این‌گونه به ERP می‌رسند، کاتالوگ این‌گونه منتشر می‌شود و هر چیزی که مسیر سریع از دست داده این‌گونه اصلاح می‌شود. هر کار ورودی cron مخصوص خود را دارد، بنابراین فقط آنچه را می‌خواهید اجرا می‌کنید.',
'Woo_Guide_Sync_Drains_Queue' => '{command} در حین اجرا صف خود را پردازش می‌کند، بنابراین این خطوط به worker جداگانه نیاز ندارند. در Windows، از Task Scheduler با برنامه {program} و همان آرگومان‌ها، با شروع در {path} استفاده کنید.',
'Woo_Or_No_Cron' => 'یا اصلاً بدون cron',
'Woo_Guide_No_Cron_Text' => 'هر زبانه اینجا در صورت درخواست همگام‌سازی می‌کند و همگام‌سازی دستی تا زمانی که صفحه باز است دسته‌های خود را پردازش می‌کند — بنابراین یک فروشگاه کوچک می‌تواند بدون هیچ ورودی cron کار کند. آنچه از دست می‌دهید همه اتفاقاتی است که وقتی کسی نگاه نمی‌کند رخ می‌دهد: سفارش‌ها فقط زمانی می‌رسند که کسی دکمه را بزند.',
