'Woo_Wp_App_Password' => 'رمز برنامه WordPress',
'Woo_Settings_Instant_Hint' => 'فروش، مرجوعی یا تعدیل، به محض ذخیره فقط موجودی همان محصولات را ارسال می‌کند، بنابراین فروشگاه ظرف چند ثانیه به‌روز می‌شود نه در همگام‌سازی ساعتی بعدی. نیازی به نصب چیز دیگری نیست — ارسال پس از پاسخ به فروش اجرا می‌شود، بنابراین صندوق هرگز منتظر WooCommerce نمی‌ماند. اطلاعات بیشتر در زبانه {guide}.',
'Woo_Settings_Instant_Off_Alert' => 'اگر خاموش بماند، فروش POS فقط در همگام‌سازی بعدی موجودی — تا یک ساعت بعد — به WooCommerce می‌رسد.',
'Woo_Settings_Auto_Products_Hint' => 'محصولی که در Stocky ایجاد، ویرایش یا تکثیر می‌شود، بلافاصله پس از ذخیره به WooCommerce ارسال می‌شود — جزئیات، قیمت، تنوع‌ها، تصاویر و سپس موجودی آن — به‌جای انتظار برای همگام‌سازی محصولات. ورودهای گروهی ارسال نمی‌شوند؛ پس از ورود، همگام‌سازی محصولات را اجرا کنید.',
'Woo_Sync_Tuning' => 'تنظیم دقیق همگام‌سازی',
'Woo_Sync_Tuning_Intro' => 'پیش‌فرض‌ها برای بیشتر فروشگاه‌ها مناسب هستند. فقط در صورتی این موارد را تغییر دهید که همگام‌سازی در هاست شما کند است یا timeout می‌شود. هر مقدار به یک بازه ایمن محدود است و پاک کردن فیلد، پیش‌فرض آن را بازمی‌گرداند.',
'Woo_Setting_This_Up' => 'راه‌اندازی',
'Woo_Setting_This_Up_Text' => 'دریافت کلیدهای API، کاربرد رمز برنامه WordPress، ورودی‌های cron برای همگام‌سازی‌های زمان‌بندی‌شده و نحوه رساندن موجودی به فروشگاه به محض تغییر — همه این‌ها، همراه با خطوط cron همین سرور آماده کپی، در زبانه راهنما قرار دارد. یک نسخه واحد، تا هرگز با عملکرد واقعی ماژول ناهماهنگ نشود.',
