'Telegram_G_Administrator' => 'مدیر',
'Telegram_G_GetUpdates_Intro' => 'برای گروه یا کانال، این آدرس را با توکن خودتان در مرورگر باز کنید و پس از ارسال پیام آن را تازه‌سازی کنید:',
'Telegram_G_Chat_Id_Note' => 'به دنبال {json} بگردید. شناسه گروه یا کانال منفی است، مثلاً {example} — همه آن را همراه با علامت منفی کپی کنید.',
'Telegram_G_Step3_Title' => 'اتصال در اینجا',
