'Telegram_G_State_Not_Configured' => 'هنوز پیکربندی نشده',
'Telegram_G_Chat_Label' => 'چت {id}',
'Telegram_G_How_Sent' => 'نحوه ارسال پیام‌ها',
'Telegram_G_A_Title' => 'فوری — نیازی به نصب چیزی نیست',
'Telegram_G_A_Body' => 'فروش، خرید، پرداخت یا هزینه‌ای که در Stocky — در POS یا پنل مدیریت — ذخیره می‌شود، {after} ذخیره شدن، در همان درخواست به Telegram ارسال می‌شود. بدون ورودی cron، بدون queue worker و صندوق‌دار هرگز منتظر Telegram نمی‌ماند: هنگام ارسال پیام، فروش قبلاً پاسخ داده شده است.',
'Telegram_G_Right_After' => 'بلافاصله پس از',
'Telegram_G_B_Title' => 'ورودی cron — برای تلاش‌های مجدد و رویدادهای پس‌زمینه',
'Telegram_G_B_Body' => 'دو نوع پیام به‌جای آن در صف خود Telegram منتظر می‌مانند: ارسالی که ناموفق بوده (Telegram برای لحظه‌ای در دسترس نبوده)، که تا سه بار دیگر طی چند دقیقه بعد دوباره تلاش می‌شود؛ و رویدادهایی که خارج از پنل مدیریت ایجاد می‌شوند — سفارش‌های واردشده از WooCommerce یا Shopify، فرمان‌های artisan. این ورودی cron آن‌ها را ارسال می‌کند و کار دیگری انجام نمی‌دهد:',
'Telegram_G_Cron_Note' => 'هر دقیقه مناسب است: اجرایی که چیزی در انتظار ندارد بلافاصله خارج می‌شود. در cPanel این مورد در {cronJobs} قرار می‌گیرد — اگر {php} قدیمی‌تر است از مسیر کامل PHP 8.2+ استفاده کنید. در Windows، از Task Scheduler با برنامه {program}، آرگومان‌های {args} و شروع در {path} استفاده کنید.',
'Telegram_G_Waiting' => '{n} در انتظار ارسال',
'Telegram_G_Nothing_Waiting' => 'چیزی در انتظار نیست',
'Telegram_G_Gave_Up' => '{n} پس از تلاش‌های مجدد رها شد',
