'Salla_Guide_1' => 'یک برنامه (خصوصی) در {link} ایجاد کرده و جریان مجوزدهی {mode} را انتخاب کنید.',
'Salla_Guide_2' => '{clientId} و {clientSecret} برنامه را در زبانه اتصال کپی کرده و ذخیره کنید.',
'Salla_Guide_3' => 'در تنظیمات برنامه، OAuth callback URL نمایش‌داده‌شده در زبانه اتصال را تنظیم کنید.',
'Salla_Guide_4' => 'در صفحه Webhooks برنامه: استراتژی امنیتی {signature} را انتخاب کنید، رمز آن را در فیلد Webhook Secret اینجا کپی کنید، URL webhook نمایش‌داده‌شده در زبانه اتصال را تنظیم کنید و حداقل در {e1}، {e2}، {e3}، {e4}، {e5} و {e6} مشترک شوید.',
'Salla_Guide_5' => 'روی {connect} کلیک کرده و برنامه را در فروشگاه خود تأیید کنید. (برنامه‌های Easy Mode به‌جای آن به‌طور خودکار از طریق webhook {webhook} متصل می‌شوند.)',
'Salla_Guide_6' => 'محصولات را دریافت یا ارسال کنید، سپس موجودی را ارسال کنید. سفارش‌های جدید به‌طور خودکار رسیده و با مرجعی مانند {ref} در بخش فروش نمایش داده می‌شوند.',
