'Presta_Not_Configured' => 'پیکربندی نشده',
'Presta_Hero_Desc' => 'همگام‌سازی محصولات، موجودی و سفارش‌ها با فروشگاه PrestaShop شما از طریق API وب‌سرویس آن.',
'Presta_Webservice_Key' => 'کلید وب‌سرویس',
'Presta_Saved_Paste_New_Key' => 'ذخیره‌شده — برای جایگزینی، کلید جدیدی وارد کنید',
'Presta_From_Menu' => 'از {menu}',
'Presta_Webservice_Key_Help' => 'وب‌سرویس را در PrestaShop ({menu}) فعال کنید، کلیدی با مجوز روی products، stock_availables، orders و customers ایجاد کرده و اینجا وارد کنید. به‌صورت فقط‌نوشتنی ذخیره می‌شود.',
'Presta_Shop_Language_Id' => 'شناسه زبان فروشگاه',
'Presta_Shop_Language_Help' => 'شناسه زبان مورد استفاده برای نام محصولات هنگام ارسال (1 = اولین زبان فروشگاه).',
'Presta_Push_Products_Desc' => 'محصولات ساده ناموجود را در PrestaShop (همراه با موجودی فعلی) ایجاد می‌کند. محصولات از قبل پیوندشده و محصولات دارای تنوع رد می‌شوند — ویرایش جزئیات محصول را در PrestaShop ادامه دهید یا برای تازه‌سازی نسخه محلی دریافت کنید.',
'Presta_Pull_Products_Desc' => 'محصولات PrestaShop را وارد می‌کند، محصولات موجود را بر اساس مرجع (SKU) تطبیق داده و بقیه را ایجاد می‌کند. ترکیب‌ها به‌عنوان محصول والد خود وارد می‌شوند.',
'Presta_Reset_Product_Confirm' => 'پیوندهای محصول بازنشانی شوند؟ سابقه سفارش‌ها پیوندهای خود را حفظ می‌کند.',
'Presta_Push_Stock_Desc' => 'موجودی فروشگاه (stock_availables) را برای همه محصولات پیوندشده به‌روزرسانی می‌کند.',
'Presta_Pull_Orders_Desc' => 'سفارش‌های فروشگاه را به‌عنوان فروش (با مرجعی مانند {ref})، از جدیدترین، وارد می‌کند. سفارش‌های از قبل واردشده و لغوشده رد می‌شوند، بنابراین دریافت منظم بی‌خطر است. PrestaShop webhook ندارد — پس از دوره‌های شلوغ این را اجرا کنید.',
'Presta_Guide_1' => 'در پنل مدیریت PrestaShop، {menu} را باز کرده و وب‌سرویس را فعال کنید.',
'Presta_Guide_2' => 'یک کلید جدید اضافه کنید و مجوز {rw} روی {products} و {stock} و مجوز {view} روی {orders} و {customers} بدهید.',
'Presta_Guide_3' => 'URL فروشگاه و کلید را در زبانه اتصال وارد کنید، ذخیره کرده و {test} را اجرا کنید.',
'Presta_Guide_4' => 'اگر فروشگاه از قبل کاتالوگ دارد، ابتدا محصولات را دریافت کنید (تطبیق بر اساس مرجع/SKU)؛ برای ایجاد محصولات ساده ناموجود ارسال کنید.',
'Presta_Guide_5' => 'هر زمان مقادیر تغییر کرد موجودی را ارسال کنید و سفارش‌ها را به‌طور منظم دریافت کنید — PrestaShop webhook ندارد، بنابراین سفارش‌ها فقط هنگام دریافت می‌رسند.',
'Presta_Identity_Title' => 'هویت محصول، مرجع (SKU) است',
'Presta_Identity_Desc' => 'کد محصول Stocky با مرجع PrestaShop تطبیق داده می‌شود. مرجع‌ها را در هر دو طرف یکسان نگه دارید؛ ترکیب‌ها (تنوع‌ها) در سفارش‌ها بر اساس مرجع تطبیق داده می‌شوند اما در این نسخه ارسال نمی‌شوند.',
'Xero_Hero_Title' => 'همگام‌سازی حسابداری Xero',
'Xero_Hero_Desc' => 'مشتریان خود را به‌عنوان مخاطبان Xero و فروش‌ها را به‌عنوان فاکتور ارسال کنید — همراه با پرداخت‌ها در صورت پیکربندی حساب بانکی.',
'Xero_App_Credentials_Accounts' => 'اعتبارنامه‌های برنامه و حساب‌ها',
'Xero_From_Dev_App' => 'از برنامه شما در developer.xero.com',
'Xero_Sales_Account_Code' => 'کد حساب فروش',
'Xero_Sales_Account_Help' => 'حساب درآمد برای ردیف‌های فاکتور (\'200\' حساب فروش پیش‌فرض Xero است).',
'Xero_Payment_Account_Code' => 'کد حساب پرداخت (اختیاری)',
'Xero_Payment_Account_Ph' => 'مثلاً 090',
'Xero_Payment_Account_Help' => 'کد یک حساب بانکی. در صورت تعیین، فروش‌های پرداخت‌شده یک پرداخت نیز روی فاکتور ثبت می‌کنند؛ برای همگام‌سازی فقط فاکتورها خالی بگذارید.',
'Xero_Auto_Sync_Sales' => 'همگام‌سازی خودکار فروش‌های جدید به‌عنوان فاکتور',
'Xero_Auto_Sync_Sales_Hint' => '(هنگام ایجاد فروش‌ها در پس‌زمینه در صف قرار می‌گیرد)',
