'Xero_Organisation' => 'سازمان',
'Xero_Disconnect_Confirm' => 'اتصال سازمان Xero قطع شود؟ همگام‌سازی تا اتصال مجدد متوقف می‌شود.',
'Xero_Redirect_Uri_Title' => 'Redirect URI برای برنامه Xero',
'Xero_Redirect_Uri_Help' => 'یک «Web app» در {link} ایجاد کرده و این redirect URI را ثبت کنید. توجه: توکن‌های دسترسی Xero خودکار تازه‌سازی می‌شوند، اما اتصالی که بیش از 60 روز غیرفعال باشد باید دوباره متصل شود.',
'Xero_Total_Customers' => 'کل مشتریان',
'Xero_Contacts_In_Xero' => 'مخاطبان در Xero',
'Xero_Total_Sales' => 'کل فروش‌ها',
'Xero_Invoices_In_Xero' => 'فاکتورها در Xero',
'Xero_Payments_Recorded' => 'پرداخت‌های ثبت‌شده',
'Xero_Push_Customers_To' => 'ارسال مشتریان به {name}',
'Xero_Push_Customers_Desc' => 'برای هر مشتری یک مخاطب Xero ایجاد یا به‌روزرسانی می‌کند. مشتری‌ای که نامش از قبل در Xero وجود دارد به همان مخاطب پیوند داده می‌شود.',
'Xero_Push_Customers' => 'ارسال مشتریان',
'Xero_Push_Sales_Invoices' => 'ارسال فروش‌ها به‌عنوان فاکتور',
'Xero_Push_Invoices_Desc' => 'برای هر فروش یک فاکتور AUTHORISED ایجاد می‌کند (شماره فاکتور = Ref فروش)، با ردیف‌های فروش به‌علاوه ردیف‌های حمل، تخفیف و مالیات تا مجموع Xero با مجموع فروش برابر باشد. فروش‌هایی که از قبل در Xero هستند رد می‌شوند — فاکتورها هرگز ویرایش نمی‌شوند. مخاطبان ناموجود در لحظه ایجاد می‌شوند.',
'Xero_Push_Invoices' => 'ارسال فاکتورها',
'Xero_Reset_Contact_Confirm' => 'پیوندهای مخاطب بازنشانی شوند؟ ارسال بعدی آن‌ها را دوباره پیوند می‌دهد یا از نو ایجاد می‌کند.',
'Xero_Reset_Contact_Links' => 'بازنشانی پیوندهای مخاطب',
'Xero_Guide_1' => 'یک {webApp} در {link} ({menu}) ایجاد کنید.',
'Xero_Guide_2' => 'redirect URI نمایش‌داده‌شده در زبانه اتصال را ثبت کنید.',
'Xero_Guide_3' => '{clientId} برنامه را کپی کرده و یک {clientSecret} ایجاد کنید؛ هر دو را اینجا وارد کرده و ذخیره کنید.',
'Xero_Guide_4' => 'روی {connect} کلیک کنید، وارد شوید و سازمانی را که می‌خواهید متصل کنید انتخاب کنید.',
'Xero_Guide_5' => 'کدهای حساب را بررسی کنید: حساب فروش ردیف‌های فاکتور را دریافت می‌کند؛ اگر فروش‌های پرداخت‌شده باید پرداخت نیز ثبت کنند، کد حساب بانکی را تعیین کنید.',
'Xero_Guide_6' => 'ابتدا مشتریان، سپس فاکتورها را ارسال کنید. شماره فاکتورها همان Refهای فروش هستند، بنابراین حتی با بازنشانی پیوندها، موارد تکراری توسط Xero رد می‌شوند.',
'Xero_Amounts_Title' => 'مبالغ به همان صورت با احتساب مالیات ارسال می‌شوند',
'Xero_Amounts_Desc' => 'فاکتورها از ردیف‌های NoTax استفاده می‌کنند که دقیقاً منعکس‌کننده فروش هستند (اقلام + حمل − تخفیف + مالیات)، بنابراین مجموع‌های Xero همیشه با مجموع‌های Stocky برابر است. حسابدار شما می‌تواند ردیف‌های مالیات و حمل را در Xero به حساب‌های مناسب نگاشت کند.',
'Xero_Org_Connected' => 'سازمان Xero متصل شد.',
'Jumia_Hero_Title' => 'همگام‌سازی بازارگاه Jumia',
'Jumia_Hero_Desc' => 'ارسال قیمت‌ها و موجودی به آگهی‌های Jumia Seller Center و ورود سفارش‌های بازارگاه به‌عنوان فروش.',
'Jumia_Api_Url_Label' => 'API URL (نقطه پایانی Seller Center کشور شما)',
'Jumia_Account_Email' => 'ایمیل حساب (User ID)',
'Jumia_Api_Key' => 'کلید API',
'Jumia_Prices_Stock' => 'قیمت‌ها و موجودی',
'Jumia_Push_Prices_Stock_Title' => 'ارسال قیمت‌ها و موجودی به Jumia',
'Jumia_Push_Prices_Stock_Desc' => 'قیمت و مقدار فعلی هر محصول (و تنوع) که SKU آن با {sku} آگهی Jumia مطابقت دارد را ارسال می‌کند. به‌روزرسانی‌ها به‌صورت فیدهای Seller Center ارسال و به‌صورت ناهمگام اعمال می‌شوند — شناسه فید در زبانه گزارش‌ها ثبت می‌شود و موارد ردشده هر قلم در صفحه وضعیت فید Seller Center نمایش داده می‌شوند.',
'Jumia_Push_Prices_Stock' => 'ارسال قیمت‌ها و موجودی',
'Jumia_Pull_Orders_Desc' => 'سفارش‌های بازارگاه را به‌عنوان فروش (با مرجعی مانند {ref}) وارد می‌کند و بر اساس Seller SKU با محصولات شما تطبیق می‌دهد. سفارش‌های از قبل واردشده و لغوشده رد می‌شوند، بنابراین دریافت منظم بی‌خطر است. پرداخت‌ها فقط برای سفارش‌های تحویل‌شده پرداخت‌شده علامت‌گذاری می‌شوند (Jumia عمدتاً پرداخت در محل است).',
'Jumia_Guide_1' => 'در Jumia {sellerCenter}، {menu} را باز کرده و یک کلید API ایجاد کنید.',
'Jumia_Guide_2' => 'API URL کشور خود (مثلاً {ng} برای نیجریه، {ke} برای کنیا، {eg} برای مصر)، ایمیل حساب Seller Center و کلید را وارد کنید — سپس {test} را اجرا کنید.',
'Jumia_Guide_3' => 'مطمئن شوید {sku} هر آگهی Jumia با کد محصول Stocky برابر است — این هویتی است که هم برای ارسال موجودی و هم برای تطبیق سفارش‌ها استفاده می‌شود.',
'Jumia_Guide_4' => 'پس از تغییرات موجودی، قیمت‌ها و موجودی را ارسال کنید؛ سفارش‌ها را به‌طور منظم دریافت کنید (Jumia در این API webhook ندارد).',
'Jumia_Guide_5' => 'ایجاد آگهی‌های جدید در Seller Center باقی می‌ماند — Jumia به ویژگی‌های خاص هر دسته‌بندی و بررسی تصاویر نیاز دارد که فقط پورتال خودش به‌خوبی انجام می‌دهد.',
'Mailchimp_Hero_Title' => 'همگام‌سازی مخاطبان Mailchimp',
'Mailchimp_Hero_Desc' => 'یک فهرست مخاطبان Mailchimp را با مشتریان خود پر نگه دارید تا بتوانید روی پایگاه مشتریان واقعی خود کمپین ایمیلی اجرا کنید.',
'Mailchimp_Account_Audience' => 'حساب و مخاطبان',
'Mailchimp_Api_Key_Ph' => 'مثلاً {example} ({menu})',
'Mailchimp_Audience_Option' => '{name} ({n} عضو)',
'Mailchimp_Load_Audiences_Ph' => 'برای انتخاب، مخاطبان را بارگذاری کنید',
'Mailchimp_Load_Audiences' => 'بارگذاری مخاطبان',
'Mailchimp_Double_Optin_Label' => 'تأیید دومرحله‌ای — اعضای جدید پیش از عضویت یک ایمیل تأیید دریافت می‌کنند',
'Mailchimp_Double_Optin_Hint' => '(برای GDPR توصیه می‌شود)',
'Mailchimp_Auto_Sync_Customers' => 'همگام‌سازی خودکار مشتریان جدید هنگام ایجاد',
'Mailchimp_With_Email' => 'دارای ایمیل',
'Mailchimp_Push_Desc' => 'هر مشتری دارای آدرس ایمیل را در مخاطبان انتخاب‌شده درج یا به‌روزرسانی می‌کند (شامل نام و تلفن). اعضای موجود وضعیت اشتراک خود را حفظ می‌کنند — هیچ کس که لغو اشتراک کرده دوباره مشترک نمی‌شود. مشتریان بدون ایمیل کنار گذاشته می‌شوند.',
'Mailchimp_Double_Optin_Off_Title' => 'تأیید دومرحله‌ای خاموش است',
'Mailchimp_Double_Optin_Off_Desc' => 'اعضای جدید بدون ایمیل تأیید به‌عنوان مشترک اضافه می‌شوند. این کار را فقط برای مشتریانی انجام دهید که قبلاً با دریافت پیام‌های بازاریابی موافقت کرده‌اند.',
'Mailchimp_Guide_1' => 'در Mailchimp، {menu} را باز کرده و یک کلید ایجاد کنید (با {suffix} تمام می‌شود — این پسوند دیتاسنتر شماست).',
'Mailchimp_Guide_2' => 'کلید را اینجا وارد کرده، ذخیره کنید، سپس روی {load} کلیک کرده و مخاطبانی را که می‌خواهید پر شود انتخاب کنید.',
'Mailchimp_Guide_3' => '{doubleOptIn} را روشن نگه دارید مگر اینکه مشتریان شما قبلاً با دریافت ایمیل‌های بازاریابی موافقت کرده باشند.',
'Mailchimp_Double_Optin_Term' => 'تأیید دومرحله‌ای',
'Mailchimp_Guide_4' => 'برای پر کردن اولیه {push} را اجرا کنید؛ {autoSync} را روشن کنید تا مشتریان جدید به‌طور خودکار اضافه شوند.',
