'Shopify_Client_Info' => 'از ژانویه 2026، Shopify دیگر برنامه سفارشی در پنل مدیریت ایجاد نمی‌کند. برنامه را در {dashboard} ایجاد کنید، دامنه‌های Admin API آن را اعطا کنید، آن را روی این فروشگاه نصب کنید و سپس Client ID و Client secret را از صفحه {settings} آن کپی کنید. ERP خودش هر 24 ساعت یک توکن دسترسی جدید دریافت می‌کند. برنامه و فروشگاه باید متعلق به یک سازمان Shopify باشند.',
