'Shopify_Entities_Lead' => 'فقط موجودیت‌هایی که اینجا روشن هستند قابل همگام‌سازی‌اند — فروشگاهی که فقط سفارش‌هایش را دریافت می‌کنید نباید با یک ارسال اشتباه محصول، کاتالوگش بازنویسی شود.',
