'Shopify_Push_Stock_On_Change' => 'ارسال موجودی به محض تغییر',
'Shopify_Push_Stock_Hint' => 'فروش، مرجوعی یا تعدیل، به محض ذخیره فقط موجودی همان محصولات را ارسال می‌کند، بنابراین فروشگاه ظرف چند ثانیه به‌روز می‌شود نه در اجرای زمان‌بندی‌شده بعدی. نیازی به نصب چیز دیگری نیست — ارسال پس از پاسخ به فروش اجرا می‌شود، بنابراین صندوق هرگز منتظر Shopify نمی‌ماند.',
