'Shopify_Auto_On_Note' => 'توسط یک ورودی cron که {cmd} را اجرا می‌کند هدایت می‌شود — بدون آن، هیچ چیز اینجا خودکار اجرا نمی‌شود. همگام‌سازی دستی به‌عنوان یک اجرا محسوب می‌شود: اجرای بعدی را به اندازه بازه مرحله به تعویق می‌اندازد.',
