'Shopify_Hook_Msg_Token' => 'روی «ثبت webhookها» در پایین کلیک کنید و API secret key برنامه را به‌عنوان رمز امضا در تنظیمات فروشگاه وارد کنید.',
'Shopify_Hook_Note_Register' => 'ثبت، اشتراک‌ها را در Shopify ایجاد کرده و به‌طور خودکار به این آدرس هدایت می‌کند. آن را به‌صورت دستی در Shopify ← Settings ← Notifications ← Webhooks اضافه نکنید: آن‌ها با رمز دیگری امضا می‌شوند و همه تحویل‌ها رد خواهند شد.',
