'Shopify_Hook_Retries' => 'Shopify تا دریافت پاسخ 2xx دوباره تلاش می‌کند و هر تحویل یک بار ثبت می‌شود — رویداد تکراری بی‌اثر است، نه سفارش تکراری.',
