'Shopify_Could_Not_Load_Store' => 'بارگذاری این فروشگاه ممکن نشد',
'Shopify_G_Lead_Store' => 'آنچه این فروشگاه برای هماهنگ ماندن نیاز دارد. همه چیز اینجا مختص همین فروشگاه است — مسیرها و شناسه‌ها واقعی هستند، بنابراین فرمان‌ها را می‌توان مستقیماً روی سرور کپی کرد.',
'Shopify_G_Lead_Generic' => 'نحوه هماهنگ ماندن فروشگاه Shopify با ERP. برای دیدن وضعیت یک فروشگاه آن را در بالا انتخاب کنید، یا همین‌طور مطالعه کنید — خط cron و URL webhook برای هر فروشگاهی که متصل کنید یکسان است.',
'Shopify_G_Ways_Note' => 'بیشتر فروشگاه‌ها هر دو را اجرا می‌کنند: اولی فروشگاه را دقیقه‌به‌دقیقه به‌روز نگه می‌دارد، دومی هر چیزی را که اولی از دست داده جبران می‌کند — webhookی که هرگز نرسید، ویرایشی که مستقیماً در پنل مدیریت Shopify انجام شد، شبی که سایت از دسترس خارج بود.',
'Shopify_G_Both_Need' => 'هر دو روش ابتدا به این نیاز دارند',
'Shopify_G_Credentials' => 'اعتبارنامه‌های Shopify',
'Shopify_G_Cred_Intro' => 'از ژانویه 2026، Shopify دیگر برنامه سفارشی را در پنل مدیریت ایجاد نمی‌کند، بنابراین دو نوع اتصال وجود دارد:',
'Shopify_G_Cred_DevDash' => '{app} (هر فروشگاهی که اکنون متصل می‌شود) — {path}. دامنه‌های Admin API را برای آنچه این فروشگاه همگام‌سازی می‌کند اعطا کنید، برنامه را روی فروشگاه نصب کنید، سپس {clientId} و {clientSecret} را از صفحه Settings برنامه در {where} کپی کنید. ERP خودش آن‌ها را با یک توکن دسترسی مبادله کرده و پیش از انقضا، هر 24 ساعت آن را تمدید می‌کند. client secret همچنین webhookها را امضا می‌کند، بنابراین به چیز دیگری نیاز نیست. برنامه و فروشگاه باید در یک سازمان Shopify باشند.',
'Shopify_G_Dev_Dashboard_App' => 'برنامه Dev Dashboard',
'Shopify_G_Cred_Legacy' => '{app} (ایجادشده در پنل مدیریت پیش از 2026) — با {token} ({prefix}) و {secret} خود به‌عنوان رمز امضای webhook بدون تغییر به کار ادامه می‌دهد. این مقدار با توکن یکسان نیست و جابه‌جا وارد کردن آن‌ها دلیل معمول رد شدن webhookهاست.',
'Shopify_G_Legacy_App' => 'برنامه سفارشی قدیمی',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'ذخیره‌شده',
'Shopify_G_Missing_Refused' => 'ناموجود — تحویل‌ها رد خواهند شد',
'Shopify_G_Where_Data_Desc' => '{path} انبار ERP که موجودی آن در این فروشگاه فروخته می‌شود و مکان Shopify که موجودی در آن نوشته می‌شود. همگام‌سازی موجودی و ورود سفارش‌ها هر دو بدون آن‌ها اجرا نمی‌شوند.',
'Shopify_G_Currently' => 'در حال حاضر: انبار {warehouse}، مکان {location}',
'Shopify_G_Not_Set_Lower' => 'تعیین نشده',
'Shopify_G_Ready' => 'آماده',
'Shopify_G_Incomplete' => 'ناقص',
'Shopify_G_Manual_Syncs' => 'همگام‌سازی‌هایی که دستی شروع می‌کنید',
'Shopify_G_Manual_Desc' => 'همگام‌سازی‌ای که از {centre} شروع می‌شود بلافاصله پاسخ می‌دهد و در پس‌زمینه، در بخش‌های کوتاهی اجرا می‌شود که هر کدام از جایی که قبلی متوقف شده ادامه می‌دهند. یک کاتالوگ بزرگ هرگز توسط هاستی که درخواست‌های طولانی وب را قطع می‌کند (LiteSpeed، nginx، load balancer) نیمه‌کاره نمی‌ماند و بستن صفحه آن را متوقف نمی‌کند. worker آن یک خط cron دیگر است:',
'Shopify_G_Cron_Copied' => 'خط cron کپی شد',
'Shopify_G_Manual_Note' => 'بدون آن، همگام‌سازی همچنان به پایان می‌رسد، اما فقط تا زمانی که صفحه مرکز همگام‌سازی باز بماند: وقتی هیچ workerی ظرف چند ثانیه اجرایی را برندارد، صفحه خودش آن را با یک درخواست کوتاه در هر بار ادامه می‌دهد. در Windows از Task Scheduler هر دقیقه استفاده کنید: برنامه {program}، آرگومان‌های {args}، شروع در {dir}.',
'Shopify_G_Then_Pick' => 'سپس نحوه هماهنگ ماندن را انتخاب کنید',
'Shopify_G_Right_Away' => 'فوری',
'Shopify_G_Stock_Live' => 'موجودی زنده',
'Shopify_G_Stock_Not_Live' => 'موجودی زنده نیست',
'Shopify_G_Realtime_Lead' => 'هر تغییر به محض وقوع، ظرف چند ثانیه ارسال می‌شود. دو نیمه، با دو کلید جداگانه: {webhooks} رویدادهای خود فروشگاه را وارد می‌کنند و {push} موجودی را خارج می‌کند.',
'Shopify_G_Webhooks_Lower' => 'webhookها',
'Shopify_G_Instant_Push_Lower' => 'ارسال فوری موجودی',
'Shopify_G_Webhooks_In' => 'Webhookها — فروشگاه ← ERP',
'Shopify_G_Webhooks_Desc' => 'سفارش‌ها، تغییرات وضعیت سفارش و ویرایش‌های محصول، مشتری و موجودی در Shopify. فروشگاه را باز کرده و در {tab} آن {button} را بزنید — دو بار زدن آن بی‌خطر است. Shopify به این آدرس ارسال می‌کند:',
'Shopify_G_Webhooks_Tab' => 'زبانه Webhookها',
'Shopify_G_Webhooks_Note' => 'آدرس باید از طریق اینترنت با HTTPS در دسترس باشد — Shopify به {localhost} یا دامنه {test} تحویل نمی‌دهد. هر تحویل یک بار ثبت می‌شود، بنابراین تلاش‌های مجدد Shopify نمی‌توانند سفارش تکراری ایجاد کنند و تحویل ناموفق قابل اجرای مجدد است. تا ذخیره شدن رمز امضای مرحله 1، تحویل‌ها رد می‌شوند.',
'Shopify_G_Instant_Out' => 'ارسال فوری موجودی — ERP ← فروشگاه',
'Shopify_G_Setting_Missed' => 'این همان تنظیمی است که اغلب نادیده گرفته می‌شود',
'Shopify_G_Pos_Not_Auto' => 'فروش POS {not} به‌خودی‌خود به Shopify نمی‌رسد. اگر خاموش باشد، فروشگاه فقط در مرحله بعدی ارسال موجودی مطلع می‌شود — و در این فاصله ممکن است واحدی را بفروشد که قبلاً در صندوق فروخته‌اید.',
'Shopify_G_Not' => 'هرگز',
'Shopify_G_Tick_Push' => '{setting} را در {where} تیک بزنید. کل راه‌اندازی همین است — بدون worker، بدون cron. هر فروش، مرجوعی و تعدیل، بلافاصله پس از ذخیره، فقط موجودی همان محصولات را ارسال می‌کند و یک فروش بیست‌ردیفی یک ارسال است، نه بیست. صندوق هرگز منتظر آن نمی‌ماند.',
'Shopify_G_This_Store' => 'این فروشگاه:',
'Shopify_G_Push_On' => 'روشن — موجودی هنگام تغییر ارسال می‌شود',
'Shopify_G_Push_Off' => 'خاموش — موجودی فقط طبق زمان‌بندی',
'Shopify_G_Push_Note' => 'فقط محصولاتی که از قبل نگاشت Shopify دارند و فقط جابه‌جایی‌های انبار این فروشگاه ارسال می‌شوند. عملیات گروهی — حذف محصول، بازنشانی انبار — موجودی را بدون ایجاد رویداد می‌نویسند، که یکی از دلایل نگه‌داشتن مرحله زمان‌بندی‌شده موجودی است.',
'Shopify_G_Nothing_Install' => 'نیازی به نصب چیز دیگری نیست',
'Shopify_G_No_Worker_Note' => 'هیچ‌کدام از دو نیمه به queue worker یا ورودی cron نیاز ندارند. webhook ورودی در همان درخواستی که Shopify ارسال می‌کند پردازش می‌شود؛ ارسال موجودی خروجی در همان فرایندی اجرا می‌شود که فروش را پردازش کرده، {after} بازگشت پاسخ — بنابراین صندوق هرگز منتظر Shopify نمی‌ماند و فروشگاهی که پاسخ نمی‌دهد پس از ده ثانیه رها شده و به ارسال زمان‌بندی‌شده بعدی موجودی سپرده می‌شود.',
'Shopify_G_After' => 'پس از',
'Shopify_G_Artisan_Note' => 'یک استثنا: تغییر موجودی ایجادشده توسط یک فرمان artisan پاسخی ندارد که پس از آن اجرا شود، بنابراین به‌جای آن در صف {queue} قرار می‌گیرد. اگر می‌خواهید این موارد نیز سریع ارسال شوند، آن صف را پردازش کنید:',
'Shopify_G_On_Schedule' => 'طبق زمان‌بندی',
'Shopify_G_On_Lower' => 'روشن',
'Shopify_G_Off_Lower' => 'خاموش',
'Shopify_G_Scheduled_Lead' => 'همه چیز هر چند وقت یک بار در هر دو جهت دوباره بررسی می‌شود. کندتر از زمان واقعی، اما همین است که در فروشگاه‌هایی که از ارسال فوری استفاده نمی‌کنند موجودی را ارسال می‌کند، webhook ازدست‌رفته را جبران می‌کند و تنها راه انتقال کل کاتالوگ است.',
'Shopify_G_Cron_Entry' => 'ورودی cron',
'Shopify_G_Cron_Entry_Desc' => 'بدون آن هیچ چیز زمان‌بندی‌شده‌ای اجرا نمی‌شود. یک خط، فقط برای این ماژول — آن را کنار هر چیز دیگری که برای زمان‌بندی انتخاب کرده‌اید اضافه کنید:',
'Shopify_G_Cron_Note' => 'هر پنج دقیقه دقیق‌ترین تفکیکی است که یک برنامه می‌تواند استفاده کند، زیرا پنج دقیقه کوتاه‌ترین بازه مرحله است. ورودی با فاصله بیشتر به حداقل تبدیل می‌شود — با {example}، مرحله‌ای که روی 5 دقیقه تنظیم شده هر 15 دقیقه اجرا می‌شود. در Windows از Task Scheduler استفاده کنید: برنامه {program}، آرگومان‌های {args}، شروع در {dir}.',
'Shopify_G_Switch_On_Plan' => 'آن را روشن کرده و برنامه را انتخاب کنید',
'Shopify_G_Plan_Desc' => '{where} کلید تعیین می‌کند که آیا cron اصلاً می‌تواند عمل کند؛ برنامه تعیین می‌کند چه کاری انجام دهد. هر {step} یک موجودیت در یک جهت با بازه خاص خود است — {first}، {second}. بازه پیش‌فرض توسط هر مرحله‌ای که کادر خود را خالی بگذارد استفاده می‌شود.',
'Shopify_G_Step_Lower' => 'مرحله',
'Shopify_G_Plan_Note' => 'اگر برنامه را خالی بگذارید، فروشگاه سفارش‌ها را دریافت و موجودی را در بازه پیش‌فرض ارسال می‌کند، که همان چیزی است که بیشتر فروشگاه‌ها می‌خواهند. سفارش‌ها فقط دریافتی هستند: Shopify جایی است که مشتری سفارش ثبت می‌کند.',
'Shopify_G_Schedule_On' => 'زمان‌بندی روشن',
'Shopify_G_Schedule_Off' => 'زمان‌بندی خاموش — فقط دستی',
'Shopify_G_When_Step_Runs' => 'یک مرحله واقعاً چه زمانی اجرا می‌شود',
'Shopify_G_When_Note' => 'یک مرحله زمانی سررسید می‌شود که از آخرین باری که همان مرحله {started}، بیش از بازه آن گذشته باشد، که از سابقه اجرا خوانده می‌شود. بنابراین همگام‌سازی‌ای که دستی شروع می‌کنید اجرای خودکار بعدی را به تعویق می‌اندازد و مرحله‌ای که مدام ناموفق است در بازه خود دوباره تلاش می‌شود، نه در هر تیک. نمای کلی فروشگاه آخرین اجرا، زمان سررسید بعدی و دلیل مسدود بودن هر مرحله را نمایش می‌دهد. اولین ارسال کاتالوگ را دستی اجرا کنید — ابتدا با {dryRun} — پیش از اینکه آن را زمان‌بندی کنید.',
'Shopify_G_Started_Lower' => 'شروع شده است',
'Shopify_G_Where_Setting' => 'محل هر تنظیم',
'Shopify_G_Where_Setting_Note' => 'همه این‌ها روی یک فروشگاه موجود هستند: {path}، سپس آیکون مداد (یا {edit} در صفحه خود فروشگاه).',
'Shopify_G_Product_Images' => 'تصاویر محصول',
'Shopify_G_Img_1' => 'تصاویر همراه با محصول در {push} ارسال می‌شوند — ابتدا تصویر اصلی، سپس گالری، سپس یکی برای هر تنوعی که تصویر خود را دارد، تا پنجاه عدد.',
'Shopify_G_Products_Push' => 'ارسال محصولات',
'Shopify_G_Img_2' => 'تصویر یک تنوع همراه با محصول بارگذاری شده و سپس {assigned}، که روش مدل‌سازی Shopify است: هر تنوع به یکی از تصاویر محصول اشاره می‌کند. تنوعی که از تصویر اصلی استفاده می‌کند آن را دو بار بارگذاری نمی‌کند.',
'Shopify_G_Assigned' => 'به آن تنوع اختصاص داده می‌شود',
'Shopify_G_Img_3' => 'تصویری که به‌صورت فایل ذخیره شده در Shopify {uploaded} می‌شود، نه پیوند، بنابراین حتی زمانی که این نصب از اینترنت در دسترس نیست کار می‌کند. تصویری که به‌صورت لینک واردشده اضافه شده با همان URL به Shopify داده می‌شود که باید به‌صورت عمومی در دسترس باشد.',
'Shopify_G_Uploaded' => 'بارگذاری',
'Shopify_G_Img_4' => 'فقط زمانی دوباره ارسال می‌شوند که واقعاً تغییر کنند — ارسالی که فقط قیمت را تغییر می‌دهد به تصاویر فروشگاه دست نمی‌زند، زیرا ارسال آن‌ها کل مجموعه را جایگزین می‌کند.',
'Shopify_G_Img_5' => 'حذف تصویر در ERP، آن را در Shopify {not} حذف نمی‌کند. آن را آنجا نیز حذف کنید، وگرنه فروشگاه همچنان آن را نمایش می‌دهد.',
'Shopify_G_Commands' => 'فرمان‌های مفید',
'Shopify_G_Command_Copied' => 'فرمان کپی شد',
'Shopify_G_Foot' => 'هر همگام‌سازی در {logs} می‌نویسد و نمای کلی هر فروشگاه نشان می‌دهد هر مرحله آخرین بار چه زمانی اجرا شده، سررسید بعدی آن چه زمانی است و در صورت وجود، چه چیزی مانع آن است. وقتی همگام‌سازی آنچه انتظار داشتید انجام نداد، ابتدا همین‌جا را بررسی کنید.',
'Shopify_G_Covers' => 'پوشش',
'Shopify_G_Covers_Rt' => 'سفارش‌ها و ویرایش‌های انجام‌شده در Shopify؛ موجودی خروجی از ERP (فروش POS، مرجوعی، تعدیل)',
'Shopify_G_Covers_Sch' => 'همه چیز، در هر دو جهت — شامل ارسال کاتالوگ و هر چیزی که مسیر سریع از دست داده',
'Shopify_G_Speed' => 'سرعت',
