'Shopify_G_Set_Entities' => 'کدام موجودیت‌ها اصلاً همگام‌سازی شوند',
'Shopify_G_Set_Entities_What' => 'خاموش در اینجا یعنی خاموش در همه جا — دستی، زمان‌بندی‌شده و webhook.',
