'StoreAdm_Eg' => 'مثلاً {example}',
'StoreAdm_Stock_Required_Available' => '{name}: مورد نیاز {need} — موجود {have}',
'StoreAdm_PG_Intro_Msg' => 'PayPal، Paystack، Flutterwave، Razorpay، bKash و SSLCommerz فقط در پرداخت فروشگاه آنلاین استفاده می‌شوند.',
'StoreAdm_PG_Intro_Desc' => 'کلیدهای Stripe به‌صورت سراسری مشترک هستند (پنل مدیریت و فروشگاه آنلاین از یک یکپارچگی Stripe استفاده می‌کنند). هر زبانه روش خود را برای پرداخت فروشگاه آنلاین روشن یا خاموش می‌کند؛ پرداخت‌های آفلاین شامل روش‌هایی است که خارج از سیستم پرداخت می‌شوند.',
'StoreAdm_PG_Used_By_Store_Only' => 'فقط در پرداخت فروشگاه آنلاین استفاده می‌شود',
'StoreAdm_PG_Gw_Key' => '{gw} Key',
'StoreAdm_PG_Gw_Secret' => '{gw} Secret',
'StoreAdm_PG_Cards_Off' => 'پرداخت با کارت خاموش است',
'StoreAdm_PG_Cards_Off_Desc' => 'کلیدهای شما حفظ می‌شوند — پرداخت فروشگاه آنلاین فقط تا زمانی که دوباره آن را روشن کنید گزینه کارت را ارائه نمی‌دهد.',
'StoreAdm_PG_No_Stripe_Key' => 'هیچ کلید Stripe ذخیره نشده',
'StoreAdm_PG_No_Stripe_Key_Desc' => 'کلید و secret Stripe خود را وارد کنید تا دریافت پرداخت با کارت در فروشگاه آنلاین آغاز شود.',
'StoreAdm_PG_Gw_Client_Id' => '{gw} Client ID',
'StoreAdm_PG_Gw_Client_Secret' => '{gw} Client Secret',
'StoreAdm_PG_Sandbox' => 'Sandbox (حالت آزمایشی)',
'StoreAdm_PG_Sandbox_Paypal_Hint' => 'روشن: از {sandbox} با اعتبارنامه‌های sandbox استفاده می‌کند؛ برای برداشت از حساب‌های واقعی در {live} خاموش کنید.',
'StoreAdm_PG_Gw_Webhook_Id_Opt' => '{gw} Webhook ID (اختیاری)',
'StoreAdm_PG_Paypal_Webhook_Hint' => 'پشتیبان برای پرداخت‌هایی که بازگشت مرورگر آن‌ها هرگز انجام نمی‌شود، به‌علاوه بازپرداخت‌ها/چارج‌بک‌ها. یک webhook در {site} ثبت کنید که به URL زیر اشاره کند (رویدادها: {events}) و Webhook ID آن را اینجا وارد کنید.',
