'StoreAdm_PG_Gw_Public_Key' => '{gw} Public Key',
'StoreAdm_PG_Gw_Secret_Key' => '{gw} Secret Key',
'StoreAdm_PG_Paystack_Test_Live' => 'حالت آزمایشی یا واقعی توسط جفت کلید تعیین می‌شود: کلیدهای {test} در حالت آزمایشی اجرا می‌شوند، کلیدهای {live} از کارت‌های واقعی برداشت می‌کنند — کلید sandbox جداگانه‌ای وجود ندارد.',
'StoreAdm_PG_Paystack_Webhook_Url' => 'URL webhook (پشتیبان اختیاری — آن را در Settings ← API Keys & Webhooks داشبورد Paystack تنظیم کنید؛ درخواست‌ها با secret key شما به روش HMAC تأیید می‌شوند):',
'StoreAdm_PG_Paystack_Disabled_Desc' => 'Paystack را روشن کرده و کلیدهای Public و Secret خود (از {site} ← Settings ← API Keys) را وارد کنید تا کارت، انتقال بانکی و پول موبایلی در پرداخت فروشگاه آنلاین پذیرفته شوند.',
