'Cr_Guide_S_booked' => 'سفارش در اختیار پیک است؛ هنوز کسی آن را جمع‌آوری نکرده است. ثبت مرسوله فقط در این مرحله قابل لغو است.',
'Cr_Guide_S_picked_up' => 'پیک بسته را جمع‌آوری کرد.',
'Cr_Guide_S_in_transit' => 'در حال جابه‌جایی بین مراکز، در گمرک یا متوقف‌شده.',
'Cr_Guide_S_out_for_delivery' => 'امروز نزد مأمور تحویل است.',
'Cr_Guide_S_failed_attempt' => 'گیرنده در محل نبود، بسته را نپذیرفت یا آدرس اشتباه بود. پیک دوباره تلاش می‌کند یا آن را برمی‌گرداند.',
'Cr_Guide_S_delivered' => 'به مشتری تحویل داده شد. مبلغ COD به وضعیت «دریافت‌شده توسط پیک» تغییر می‌کند.',
'Cr_Guide_S_returning' => 'در راه بازگشت به شما.',
'Cr_Guide_S_returned' => 'به شما بازگشت: در «مرجوعی‌های در انتظار بررسی» منتظر می‌ماند، یا به‌طور خودکار به موجودی بازمی‌گردد.',
'Cr_Guide_S_cancelled' => 'ثبت مرسوله لغو شد.',
'Cr_Guide_T_Booking' => 'ثبت سفارش‌ها',
'Cr_Guide_B_Booking' => '«ارسال به پیک» فرم را از روی فروش پر می‌کند: گیرنده، آدرس، مبلغ باقی‌مانده به‌عنوان COD، و وزن کالاها. پیک‌هایی که فهرست شهرهای خاص خود را دارند یک انتخابگر نمایش می‌دهند و انتخاب شما برای آن شهر به خاطر سپرده می‌شود. سرویس‌های تجمیع‌کننده، DHL، FedEx، UPS و Lalamove گزینه «مقایسه نرخ‌ها» را ارائه می‌دهند: یک قیمت انتخاب کنید و «ثبت» آن را خریداری می‌کند. چند فروش را می‌توان به‌طور همزمان از فهرست فروش‌ها ثبت کرد.',
'Cr_Guide_T_Cod' => 'پرداخت در محل',
'Cr_Guide_B_Cod' => 'یک بسته COD از «دریافت‌نشده» به «دریافت‌شده توسط پیک» (هنگام تحویل) و سپس به «تسویه‌شده با شما» می‌رود. پیک‌هایی که تسویه‌ها را گزارش می‌کنند مرحله آخر را خودشان انجام می‌دهند؛ برای بقیه از «به‌روزرسانی COD» استفاده کنید. اگر در تنظیمات پیک حسابی انتخاب شده باشد، تسویه به‌عنوان پرداخت روی فروش ثبت می‌شود. هزینه‌های پیک را می‌توان پس از نهایی شدن بسته به‌عنوان هزینه ذخیره کرد.',
'Cr_Guide_T_Returns' => 'بسته‌های برگشتی',
'Cr_Guide_B_Returns' => 'به‌طور پیش‌فرض، بسته برگشتی در «مرسوله‌های پیک» زیر «مرجوعی‌های در انتظار بررسی» منتظر می‌ماند. «بازگشت به موجودی» برای کل سفارش یک مرجوعی فروش ایجاد کرده و اقلام را به موجودی بازمی‌گرداند؛ «نادیده گرفتن» چیزی را بازنمی‌گرداند و برای بسته‌های آسیب‌دیده یا مفقودشده است. در عوض می‌توانید در تنظیمات پیک، بازگشت خودکار به موجودی را فعال کنید.',
'Cr_Guide_T_Customers' => 'پیام‌های مشتری و صفحه رهگیری',
'Cr_Guide_B_Customers' => '«اعلان‌های مشتری» در تنظیمات پیک، در وضعیت‌هایی که علامت می‌زنید SMS، ایمیل یا WhatsApp ارسال می‌کند، هر کدام یک بار برای هر بسته و با متن دلخواه شما. صفحه رهگیری در فروشگاه آنلاین شما به مشتریان امکان می‌دهد بسته را با شماره رهگیری، یا با شماره سفارش و تلفن، پیگیری کنند. مشتریانی که اغلب بسته‌ها را برگشت می‌دهند، هنگام ثبت مرسوله نشان ریسک مرجوعی دریافت می‌کنند.',
'Cr_Guide_T_Labels' => 'برچسب‌ها',
'Cr_Guide_B_Labels' => '«چاپ برچسب» در صورتی که پیک برچسب خودش را صادر کند (PDF، لینک یا تصویر) همان را ارائه می‌دهد، در غیر این صورت یک برچسب Stocky با بارکد رهگیری و مبلغ قابل دریافت. برای چاپ، پنجره‌های بازشو را برای این سایت مجاز کنید. DHL، FedEx و UPS برچسب خود را فقط یک بار، هنگام ثبت، ارائه می‌دهند و Stocky آن را برای چاپ مجدد نگه می‌دارد.',
'Cr_Guide_T_Faq' => 'رفع اشکال',
'Cr_Guide_Q_Test' => 'آزمایش اتصال ناموفق است',
'Cr_Guide_A_Test' => 'کلیدهای آزمایشی با حالت «آزمایشی» و کلیدهای واقعی با حالت «عملیاتی» استفاده می‌شوند؛ این دو با هم متفاوت‌اند. برای دانستن دلیل دقیق، «لاگ‌های پیک» را باز کرده و پاسخ پیک را بخوانید.',
'Cr_Guide_Q_City' => 'پیک شهر یا آدرس را نمی‌پذیرد',
'Cr_Guide_A_City' => 'شهر را از فهرست شهرهای پیک در فرم ثبت انتخاب کنید؛ پیک‌ها فقط نام‌های خودشان را می‌پذیرند. پیک‌هایی که با آدرس پستی کار می‌کنند به استان، کد پستی و کد دوحرفی کشور نیز نیاز دارند.',
'Cr_Guide_Q_Webhook' => 'وضعیت‌ها خودبه‌خود تغییر نمی‌کنند',
'Cr_Guide_A_Webhook' => 'برای پیک‌هایی که به‌روزرسانی ارسال می‌کنند، بررسی کنید که Webhook URL نزد پیک ثبت شده باشد: «لاگ‌های پیک» هر به‌روزرسانی دریافتی یا دلیل رد شدن آن (مثلاً کلید مخفی اشتباه) را نشان می‌دهد. سایر پیک‌ها طبق زمان‌بندی تنظیمات پیک بررسی می‌شوند و «بررسی فوری وضعیت» بلافاصله استعلام می‌گیرد.',
'Cr_Guide_Q_Stuck' => 'یک مرسوله خطای بررسی وضعیت نشان می‌دهد',
'Cr_Guide_A_Stuck' => 'پیک آخرین بررسی‌ها را رد کرده است؛ دلیل آن روی مرسوله و در «لاگ‌های پیک» قابل مشاهده است. پس از چند شکست متوالی، مرسوله دیگر به‌طور خودکار بررسی نمی‌شود: علت را برطرف کنید، سپس از «بررسی فوری وضعیت» استفاده کنید.',
'Cr_Guide_Q_Label' => 'هنگام چاپ برچسب چیزی باز نمی‌شود',
'Cr_Guide_A_Label' => 'مرورگر شما پنجره بازشو را مسدود کرده است. پنجره‌های بازشو را برای این سایت مجاز کرده و دوباره تلاش کنید.',
'Cr_Guide_Q_Cod' => 'تسویه COD روی فروش ثبت نشد',
'Cr_Guide_A_Cod' => 'در تنظیمات پیک، پرداخت در محل باید فعال باشد و یک حساب انتخاب شده باشد. بدون حساب، تسویه‌ها فقط به‌عنوان تسویه‌شده علامت‌گذاری می‌شوند.',
