'Cr_WhatsApp_Text_Help' => 'WhatsApp همان متن پیام را از طریق یکپارچه‌سازی‌ها ← WhatsApp ارسال کرده و آن را همراه با سایر پیام‌های WhatsApp شما ثبت می‌کند. Meta پیام‌های متنی آزاد را فقط تا 24 ساعت پس از آخرین پیام مشتری به شما تحویل می‌دهد.',
