'Tfa_Codes_Save' => 'این کدهای بازیابی را در جای امنی نگه دارید. اگر گوشی خود را گم کنید، هر کد یک بار شما را وارد می‌کند. این کدها دوباره نمایش داده نمی‌شوند.',
'Tfa_Reset' => 'بازنشانی دومرحله‌ای',
'Tfa_Reset_Title' => 'احراز هویت دومرحله‌ای بازنشانی شود؟',
'Tfa_Reset_Help' => ':name فقط با رمز عبور خود وارد می‌شود و سپس می‌تواند برنامه احراز هویت خود را دوباره راه‌اندازی کند. این کار را فقط پس از اطمینان از هویت درخواست‌کننده انجام دهید.',
'Tfa_Guide_Lead' => 'احراز هویت دومرحله‌ای (2FA) یک مرحله دوم به ورود اضافه می‌کند: پس از رمز عبور، کارکنان یک کد 6 رقمی از برنامه احراز هویت روی گوشی خود وارد می‌کنند. دیگر یک رمز عبور سرقت‌شده یا حدس‌زده‌شده برای ورود کافی نیست.',
