'Tfa_Guide_Staff_Title' => 'برای هر یک از کارکنان',
'Tfa_Guide_App_Title' => 'نصب برنامه احراز هویت',
'Tfa_Guide_App_Text' => 'هر برنامه‌ای که از کدهای استاندارد 6 رقمی (TOTP) پشتیبانی کند کار می‌کند. این برنامه‌ها رایگان هستند و آفلاین کار می‌کنند:',
'Tfa_Guide_Enable_Title' => 'فعال کردن از پروفایل',
'Tfa_Guide_Enable_1' => 'پروفایل (منوی آواتار در بالا سمت راست) را باز کنید و کارت «احراز هویت دومرحله‌ای» را پیدا کنید.',
'Tfa_Guide_Enable_2' => 'روی «فعال کردن» کلیک کنید و با رمز عبور فعلی تأیید کنید.',
'Tfa_Guide_Enable_3' => 'QR کد را با برنامه اسکن کنید، یا کلید نمایش‌داده‌شده زیر آن را تایپ کنید.',
'Tfa_Guide_Enable_4' => 'برای پایان، کد 6 رقمی نمایش‌داده‌شده در برنامه را وارد کنید.',
'Tfa_Guide_Open_Profile' => 'باز کردن پروفایل من',
'Tfa_Guide_Codes_Title' => 'ذخیره کدهای بازیابی',
'Tfa_Guide_Codes_Text' => 'بلافاصله پس از راه‌اندازی، 8 کد بازیابی یک بار نمایش داده می‌شود. هر کد یک بار جایگزین کد گوشی می‌شود — برای گوشی گم‌شده، خراب یا بازنشانی‌شده. آن‌ها را دانلود یا کپی کنید و در جای امنی، دور از گوشی، نگه دارید.',
'Tfa_Guide_Codes_Note' => 'کدها رو به اتمام است؟ گزینه «کدهای بازیابی جدید» در پروفایل کل مجموعه را جایگزین می‌کند؛ کدهای قبلی دیگر کار نمی‌کنند.',
'Tfa_Guide_Signin_Title' => 'ورود',
'Tfa_Guide_Signin_Text' => 'پس از ایمیل و رمز عبور، صفحه ورود کد فعلی برنامه را درخواست می‌کند. کدها هر 30 ثانیه تغییر می‌کنند و هر کد فقط یک بار کار می‌کند.',
'Tfa_Guide_Signin_Trust' => 'علامت زدن «دیگر در این دستگاه سؤال نشود» باعث می‌شود تا :days روز در آن مرورگر کد درخواست نشود.',
'Tfa_Guide_Signin_Recovery' => 'گوشی در دسترس نیست؟ روی «استفاده از کد بازیابی» کلیک کنید و یکی از کدهای ذخیره‌شده را تایپ کنید.',
'Tfa_Guide_Admin_Title' => 'برای مدیران',
'Tfa_Guide_Require_Title' => 'اجباری کردن',
'Tfa_Guide_Require_Text' => 'گزینه «الزامی کردن احراز هویت دومرحله‌ای» را در این کارت فعال کنید، سپس نقش‌هایی را که باید از آن استفاده کنند انتخاب کنید — یا برای همه کاربران فهرست را خالی بگذارید. برای ذخیره روی «ثبت» کلیک کنید.',
'Tfa_Guide_Require_Next' => 'هیچ‌کس از سیستم خارج نمی‌شود. کاربرانی که هنوز 2FA ندارند، در ورود بعدی و پیش از ورود، در صفحه ورود مراحل راه‌اندازی را طی می‌کنند و کدهای بازیابی خود را همان‌جا می‌بینند.',
'Tfa_Guide_Require_Note' => 'کاربرانی که این گزینه برایشان الزامی است نمی‌توانند آن را از پروفایل خود غیرفعال کنند.',
'Tfa_Guide_Trust_Title' => 'دستگاه‌های مورد اعتماد',
'Tfa_Guide_Trust_Text' => 'گزینه «به خاطر سپردن دستگاه‌های مورد اعتماد» تعیین می‌کند یک مرورگر پس از ورود موفق تا چه مدت می‌تواند از وارد کردن کد صرف‌نظر کند. برای رایانه‌های مشترک یا عمومی مانند POS داخل فروشگاه، «همیشه کد درخواست شود» را انتخاب کنید.',
'Tfa_Guide_Trust_Note' => 'کاهش این عدد، مدت اعتماد دستگاه‌های فعلی را نیز کوتاه می‌کند؛ غیرفعال کردن یا بازنشانی 2FA همه آن‌ها را فراموش می‌کند.',
'Tfa_Guide_Lost_Title' => 'گوشی گم‌شده و بدون کد بازیابی',
'Tfa_Guide_Lost_Text' => 'در صفحه کاربران، کاربران دارای 2FA در ستون 2FA مقدار «فعال» را نشان می‌دهند. دکمه سپر در ستون عملیات آن را بازنشانی می‌کند: کاربر فقط با رمز عبور وارد می‌شود و برنامه را دوباره راه‌اندازی می‌کند (یا اگر الزامی باشد، از او خواسته می‌شود).',
'Tfa_Guide_Lost_Warn' => 'پیش از بازنشانی از هویت درخواست‌کننده اطمینان حاصل کنید — بازنشانی، محافظتی را که 2FA به آن حساب می‌دهد حذف می‌کند.',
'Tfa_Guide_Open_Users' => 'باز کردن کاربران',
'Tfa_Guide_Mobile_Title' => 'اپلیکیشن موبایل و API',
'Tfa_Guide_Mobile_Text' => 'اپلیکیشن موبایل و نقطه پایانی توکن API همین کد را درخواست می‌کنند. اگر 2FA برای کاربری الزامی باشد که هنوز آن را راه‌اندازی نکرده است، او باید یک بار از طریق وب وارد شود تا این کار را انجام دهد.',
'Tfa_Guide_Protect_Title' => 'محافظت داخلی',
'Tfa_Guide_Protect_1' => '5 کد اشتباه، وارد کردن کد را برای آن کاربر به مدت 15 دقیقه مسدود می‌کند، صرف‌نظر از تنظیمات قفل حساب در بالا.',
'Tfa_Guide_Protect_2' => 'هر کد و هر کد بازیابی فقط یک بار کار می‌کند.',
'Tfa_Guide_Protect_3' => 'با فعال بودن «ثبت فعالیت ورود»، کدهای اشتباه در فهرست فعالیت ورود با عنوان «کد 2FA اشتباه» نمایش داده می‌شوند.',
'Tfa_Guide_Trouble_Title' => 'عیب‌یابی',
'Tfa_Guide_Faq_Clock_Q' => 'خطای «این کد معتبر نیست» با یک کد تازه',
'Tfa_Guide_Faq_Clock_A' => 'احتمالاً ساعت گوشی دقیق نیست. کدها به زمان وابسته‌اند: تاریخ و ساعت گوشی را روی خودکار (زمان شبکه) تنظیم کنید، سپس کد بعدی را امتحان کنید.',
'Tfa_Guide_Faq_Phone_Q' => 'انتقال به گوشی جدید',
'Tfa_Guide_Faq_Phone_A' => 'یا از قابلیت انتقال خود برنامه احراز هویت استفاده کنید، یا 2FA را در پروفایل غیرفعال و سپس با گوشی جدید دوباره فعال کنید (اگر الزامی است، به جای آن از یک مدیر بخواهید آن را بازنشانی کند).',
'Tfa_Guide_Faq_Locked_Q' => '«تعداد کدهای نامعتبر بیش از حد مجاز است»',
'Tfa_Guide_Faq_Locked_A' => 'به مدت زمان نمایش‌داده‌شده (حداکثر 15 دقیقه) صبر کنید، یا از یک مدیر بخواهید 2FA کاربر را بازنشانی کند.',
'Tfa_Guide_Faq_Key_Q' => 'پس از انتقال سرور، هیچ کاربر دارای 2FA نمی‌تواند وارد شود',
'Tfa_Guide_Faq_Key_A' => 'رمزهای 2FA با APP_KEY موجود در فایل .env رمزنگاری می‌شوند. هنگام انتقال یا بازیابی برنامه، همان APP_KEY را حفظ کنید؛ اگر تغییر کرده باشد، یک مدیر بدون 2FA باید کاربران آسیب‌دیده را بازنشانی کند.',
'Tfa_Guide_Button' => 'راهنما',
'Tfa_Guide_Title' => 'راهنمای احراز هویت دومرحله‌ای',
'Sec_2fa_Pending' => ':count نفر هنوز باید آن را راه‌اندازی کنند',
'Sec_2fa_See_Who' => 'مشاهده افراد',
'Sec_2fa_Grace_Off' => 'هیچ — راه‌اندازی در ورود بعدی',
'Sec_2fa_Applied' => ':count کاربر از سیستم خارج شدند.',
'Tfa_Guide_Rollout_Title' => 'اعمال برای همه کاربران',
'Tfa_Guide_Rollout_1' => 'ابتدا آن را برای حساب خودتان فعال کنید (پروفایل)، تا با مراحل آشنا شوید.',
'Tfa_Guide_Rollout_2' => 'به تیم خود بگویید کدام برنامه را نصب کنند و اینکه راه‌اندازی هنگام ورود یک دقیقه طول می‌کشد.',
'Tfa_Guide_Rollout_3' => 'گزینه «الزامی کردن احراز هویت دومرحله‌ای» را فعال کنید، «الزامی برای» را خالی بگذارید (= همه کاربران) و در صورت تمایل یک مهلت تعیین کنید. روی «ثبت» کلیک کنید.',
'Tfa_Guide_Rollout_4' => 'روی «خروج کاربران بدون 2FA» کلیک کنید تا افرادی که از قبل وارد شده‌اند همین حالا آن را راه‌اندازی کنند، نه در یک ورود بعدی. شما وارد باقی می‌مانید.',
'Tfa_Guide_Rollout_5' => 'پیشرفت را با شمارنده این کارت یا فیلتر «نیاز به راه‌اندازی» در صفحه کاربران دنبال کنید.',
'Tfa_Guide_Rollout_Note' => 'با تعیین مهلت، صفحه راه‌اندازی تا پایان مهلت گزینه «بعداً یادآوری کن» را نشان می‌دهد؛ پس از آن، راه‌اندازی برای ورود الزامی است.',
'Tfa_Guide_Customers_Title' => 'حساب‌های مشتریان (فروشگاه و پورتال مشتریان)',
'Tfa_Guide_Customers_Text' => 'مشتریان نیز می‌توانند از حساب‌های خود محافظت کنند. این گزینه برای هر مشتری اختیاری است و هرگز اجباری نمی‌شود: آن را در تنظیمات فروشگاه ← کنترل دسترسی ثبت‌نام (فروشگاه آنلاین) و پورتال مشتریان ← تنظیمات پورتال (پورتال مشتریان) فعال کنید.',
'Tfa_Guide_Customers_1' => 'مشتریان آن را از حساب من (فروشگاه) یا پروفایل (پورتال) فعال می‌کنند.',
'Tfa_Guide_Customers_2' => 'آن‌ها کدی را که با ایمیل ارسال می‌شود — ساده‌ترین روش، بدون نیاز به برنامه — یا یک برنامه احراز هویت همراه با کدهای بازیابی انتخاب می‌کنند.',
'Tfa_Guide_Customers_3' => 'کدهای ایمیلی به تنظیمات ایمیل فعال نیاز دارند (تنظیمات ← تنظیمات ایمیل). این کدها پس از 10 دقیقه منقضی می‌شوند.',
'Tfa_Guide_Customers_4' => 'غیرفعال کردن این گزینه در آینده، از راه‌اندازی‌های جدید جلوگیری می‌کند؛ مشتریانی که از قبل از آن استفاده می‌کنند همچنان کد از آن‌ها خواسته می‌شود و می‌توانند خودشان آن را غیرفعال کنند.',
'Tfa_Required_Grace_Notice' => 'مدیر سیستم احراز هویت دومرحله‌ای را الزامی کرده است. می‌توانید هنگام ورود تا :date آن را به تعویق بیندازید؛ پس از آن، راه‌اندازی الزامی است.',
'Tfa_Filter_All' => '2FA: همه کاربران',
'Tfa_Needs_Setup_Help' => 'طبق تنظیمات سیستم > امنیت الزامی است؛ در ورود بعدی از کاربر خواسته می‌شود آن را راه‌اندازی کند.',
'Tfa_Needs_Setup' => 'نیاز به راه‌اندازی',
'Tfa_Filter_On' => '2FA فعال',
'Tfa_Filter_Off' => '2FA غیرفعال',
'Tfa_Filter_Pending' => 'نیاز به راه‌اندازی (الزامی)',
'Store_Customer_2fa' => 'تأیید دومرحله‌ای',
'Store_Customer_2fa_Help' => 'به مشتریان اجازه می‌دهد با کدی که از طریق ایمیل ارسال می‌شود یا از برنامه احراز هویت، از حساب خود محافظت کنند؛ این گزینه از حساب من فعال می‌شود. برای هر مشتری اختیاری است.',
'Portal_2fa' => 'تأیید دومرحله‌ای',
'Portal_2fa_Help' => 'به مشتریان اجازه می‌دهد با کدی که از طریق ایمیل ارسال می‌شود یا از برنامه احراز هویت، از ورود به پورتال خود محافظت کنند؛ این گزینه از پروفایلشان فعال می‌شود. برای هر مشتری اختیاری است.',
'Two_factor_grace_notice' => 'از :date الزامی است. تا آن زمان می‌توانید راه‌اندازی را به بعد موکول کنید.',
'Two_factor_remind_later' => 'بعداً یادآوری کن',
'Sec_2fa_Grace' => 'مهلت',
'Sec_2fa_Grace_Help' => 'به کاربران اجازه می‌دهد تا پایان مهلت، در صفحه راه‌اندازی «بعداً یادآوری کن» را انتخاب کنند، تا کار هیچ‌کس در میانه شیفت متوقف نشود. از زمان فعال شدن این الزام محاسبه می‌شود.',
'Sec_2fa_Grace_Ends' => 'راه‌اندازی از :date اجباری می‌شود.',
'Sec_2fa_Apply' => 'اعمال فوری',
'Sec_2fa_Apply_Help' => 'از افرادی که از قبل وارد شده‌اند فقط در ورود بعدی سؤال می‌شود، که با «مرا به خاطر بسپار» ممکن است ماه‌ها طول بکشد. این گزینه همه کسانی را که باید 2FA را راه‌اندازی کنند و هنوز نکرده‌اند، در همه دستگاه‌ها از سیستم خارج می‌کند تا هنگام ورود دوباره آن را راه‌اندازی کنند. شما وارد باقی می‌مانید.',
